import crypto from "crypto";
import { getEnv } from "../config/env";
import { getRedisClient, isRedisAvailable } from "../utils/redis";
import { hashPassword, generateSecureToken, safeCompareStrings } from "../utils/crypto";
import { sendSimulatedEmail } from "../utils/emailService";
import { UserRepository } from "../repositories/user.repository";
import { SessionService } from "./session.service";
import { BadRequestError, ConflictError } from "../errors/app-error";
import { UserSession } from "../../types";

import { bestEffort } from "../utils/best-effort";
const TTL_SECONDS = 15 * 60;
const RESEND_COOLDOWN_MS = 30 * 1000;
const MAX_ATTEMPTS = 5;

interface PendingRegistration {
  email: string;
  fullName: string;
  passwordHash: string;
  codeHash: string;
  attempts: number;
  createdAt: number;
  expiresAt: number;
}

/**
 * Email-verified sign-up. No account exists until the mailbox owner enters the emailed code, so a third party
 * who registers someone else's address cannot create (or pre-seed the password of) that person's account.
 */
export class RegistrationVerificationService {
  private userRepo = new UserRepository();
  private sessionService = new SessionService();
  private memory = new Map<string, PendingRegistration>();

  private key(email: string) {
    return `happenins:reg:pending:${email}`;
  }

  private hashCode(email: string, code: string) {
    return crypto.createHmac("sha256", getEnv().JWT_SECRET).update(`${email}:${code.trim()}`).digest("hex");
  }

  private async load(email: string): Promise<PendingRegistration | null> {
    const redis = getRedisClient();
    if (redis && isRedisAvailable()) {
      const raw = await redis.get(this.key(email)).catch(() => null);
      if (raw) return JSON.parse(raw);
    }
    const mem = this.memory.get(this.key(email));
    return mem && mem.expiresAt > Date.now() ? mem : null;
  }

  private async save(p: PendingRegistration) {
    const ttl = Math.max(1, Math.floor((p.expiresAt - Date.now()) / 1000));
    const redis = getRedisClient();
    if (redis && isRedisAvailable()) {
      await redis.set(this.key(p.email), JSON.stringify(p), "EX", ttl);
      return;
    }
    this.memory.set(this.key(p.email), p);
  }

  private async remove(email: string) {
    this.memory.delete(this.key(email));
    const redis = getRedisClient();
    if (redis && isRedisAvailable()) await redis.del(this.key(email)).catch(bestEffort("redis.del pending registration"));
  }

  /** Response is identical whether or not the address already has an account (no enumeration). */
  async start(
    data: { email: string; fullName: string; password: string }
  ): Promise<{ requiresVerification: true; email: string; expiresInSeconds: number; otpPreview?: string }> {
    const email = data.email.trim().toLowerCase();
    if (!data.password || data.password.trim().length < 8) {
      throw new BadRequestError("Password must be at least 8 characters in length.");
    }
    const base = { requiresVerification: true as const, email, expiresInSeconds: TTL_SECONDS };

    const existing = await this.userRepo.findByEmail(email);
    if (existing && existing.isEmailVerified) {
      await sendSimulatedEmail(
        email,
        "Happenins sign-up attempt",
        `Hi ${existing.fullName},\n\nSomeone tried to create a Happenins account with this email address, but you already have one.\n\nIf it was you, simply sign in (or use "Forgot password").\nIf not, you can safely ignore this message.`
      );
      return base;
    }

    const current = await this.load(email);
    if (current && Date.now() - current.createdAt < RESEND_COOLDOWN_MS) {
      return base; // cooldown: do not resend or overwrite within 30 seconds
    }

    const code = crypto.randomInt(100000, 1000000).toString();
    const now = Date.now();
    await this.save({
      email,
      fullName: data.fullName.trim(),
      passwordHash: await hashPassword(data.password.trim()),
      codeHash: this.hashCode(email, code),
      attempts: 0,
      createdAt: now,
      expiresAt: now + TTL_SECONDS * 1000,
    });

    await sendSimulatedEmail(
      email,
      `Your Happenins verification code: ${code}`,
      `Hi ${data.fullName.trim()},\n\nYour Happenins email verification code is:\n\n  >>>  ${code}  <<<\n\nIt is valid for 15 minutes. If you did not sign up, ignore this email - no account has been created.\n\nWarm regards,\nThe Happenins Team`
    );

    return { ...base, otpPreview: process.env.NODE_ENV !== "production" ? code : undefined };
  }

  async complete(
    emailRaw: string,
    code: string,
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ user: UserSession; accessToken: string; rawRefreshToken: string }> {
    const email = emailRaw.trim().toLowerCase();
    const pending = await this.load(email);
    const invalid = new BadRequestError("Invalid or expired verification code. Please sign up again to get a new code.");
    if (!pending || pending.expiresAt < Date.now()) throw invalid;

    if (pending.attempts >= MAX_ATTEMPTS) {
      await this.remove(email);
      throw new BadRequestError("Too many incorrect attempts. Please sign up again to get a new code.");
    }

    if (!safeCompareStrings(this.hashCode(email, code), pending.codeHash)) {
      pending.attempts += 1;
      await this.save(pending);
      throw invalid;
    }
    await this.remove(email); // single use

    let user = await this.userRepo.findByEmail(email);
    if (user) {
      // Legacy unverified account: the verified mailbox owner now sets its password
      await this.userRepo.setVerifiedWithPassword(user.id, pending.passwordHash, pending.fullName);
      await this.sessionService.revokeAllUserSessions(user.id, "EMAIL_VERIFIED");
    } else {
      user = await this.userRepo.createUser({
        id: "usr_" + generateSecureToken(8),
        email,
        fullName: pending.fullName,
        passwordHash: pending.passwordHash,
        role: "USER", // public registration always yields a plain USER
        isEmailVerified: true,
        emailVerifiedAt: new Date(),
      });
    }

    const { rawRefreshToken, accessToken, user: sessionUser } = await this.sessionService.createSession(user.id, ipAddress, userAgent);
    return { user: sessionUser, accessToken, rawRefreshToken };
  }

  /**
   * Used only when FEATURE_EMAIL_VERIFICATION_REQUIRED is off (typically local development): the account and
   * session are created immediately and the address stays unverified. Unlike start(), this reveals whether an
   * address is already registered. Google / email-code sign-in still claims unverified accounts safely.
   */
  async registerUnverified(
    data: { email: string; fullName: string; password: string },
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ user: UserSession; accessToken: string; rawRefreshToken: string }> {
    const email = data.email.trim().toLowerCase();
    if (!data.password || data.password.trim().length < 8) {
      throw new BadRequestError("Password must be at least 8 characters in length.");
    }
    if (await this.userRepo.findByEmail(email)) {
      throw new ConflictError("An account with this email address already exists. Try signing in.");
    }
    const user = await this.userRepo.createUser({
      id: "usr_" + generateSecureToken(8),
      email,
      fullName: data.fullName.trim(),
      passwordHash: await hashPassword(data.password.trim()),
      role: "USER",
      isEmailVerified: false,
    });
    const { rawRefreshToken, accessToken, user: sessionUser } = await this.sessionService.createSession(user.id, ipAddress, userAgent);
    return { user: sessionUser, accessToken, rawRefreshToken };
  }
}
