import { z } from "zod";

/**
 * Normalizes an email address or domain string.
 * Strips whitespace, converts to lowercase, removes any leading '@'.
 */
export function normalizeDomain(input: string): string {
  if (!input) return "";
  let clean = input.trim().toLowerCase();
  if (clean.startsWith("@")) {
    clean = clean.substring(1).trim();
  }
  return clean;
}

/**
 * Extracts normalized domain from an email address.
 */
export function extractEmailDomain(email: string): string {
  if (!email || !email.includes("@")) return "";
  const parts = email.trim().toLowerCase().split("@");
  return normalizeDomain(parts[parts.length - 1]);
}

/**
 * Validates domain string format.
 */
export function isValidDomainFormat(domain: string): boolean {
  const norm = normalizeDomain(domain);
  if (!norm || norm.length < 3 || !norm.includes(".")) return false;
  // Basic domain regex validation
  const domainRegex = /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$/i;
  return domainRegex.test(norm);
}

/**
 * Checks if a user's domain matches any allowed domain in the access policy.
 * 
 * Rules (Section H):
 * - Exact match: userDomain === allowedDomain
 * - Subdomain match: userDomain.endsWith('.' + allowedDomain)
 * - Inverse matching IS STRICTLY FORBIDDEN: an allowed domain "student.rbunagpur.in"
 *   CANNOT match a user with domain "rbunagpur.in".
 */
export function isDomainAllowed(userEmail: string, allowedDomainsRaw: string | string[]): boolean {
  const userDomain = extractEmailDomain(userEmail);
  if (!userDomain || !isValidDomainFormat(userDomain)) {
    return false;
  }

  let allowedDomainsList: string[] = [];
  if (typeof allowedDomainsRaw === "string") {
    try {
      const parsed = JSON.parse(allowedDomainsRaw);
      if (Array.isArray(parsed)) {
        allowedDomainsList = parsed;
      } else {
        allowedDomainsList = [allowedDomainsRaw];
      }
    } catch {
      allowedDomainsList = allowedDomainsRaw.split(",").map((s) => s.trim());
    }
  } else if (Array.isArray(allowedDomainsRaw)) {
    allowedDomainsList = allowedDomainsRaw;
  }

  if (allowedDomainsList.length === 0) {
    // If no specific domains listed, public access
    return true;
  }

  for (const rawAllowed of allowedDomainsList) {
    const allowedDomain = normalizeDomain(rawAllowed);
    if (!allowedDomain || !isValidDomainFormat(allowedDomain)) continue;

    // 1. Exact match
    if (userDomain === allowedDomain) {
      return true;
    }

    // 2. Subdomain match (e.g. user student.rbunagpur.in matches allowed rbunagpur.in)
    if (userDomain.endsWith("." + allowedDomain)) {
      return true;
    }
  }

  return false;
}

/**
 * Enforces institution access policy for an event reservation/transfer.
 * Throws an error or returns eligibility status with reason.
 */
export function checkInstitutionEligibility(user: {
  email: string;
  isEmailVerified?: boolean;
  emailVerifiedAt?: Date | null;
}, policy: {
  policyType: string; // "PUBLIC" | "INSTITUTION_ONLY" | "INVITE_ONLY"
  allowedDomains?: string | string[];
  requireVerifiedEmail?: boolean;
  customRestrictionMessage?: string | null;
} | null): { allowed: boolean; reason?: string } {
  if (!policy || policy.policyType === "PUBLIC") {
    return { allowed: true };
  }

  if (policy.policyType === "INSTITUTION_ONLY") {
    // Check email verification if required
    const isVerified = Boolean(user.isEmailVerified || user.emailVerifiedAt);
    const requireVerified = policy.requireVerifiedEmail !== false;

    if (requireVerified && !isVerified) {
      return {
        allowed: false,
        reason: "You must have a verified institutional email address to access or reserve tickets for this event. Please verify your email first.",
      };
    }

    // Check domain eligibility
    const domainOk = isDomainAllowed(user.email, policy.allowedDomains || "[]");
    if (!domainOk) {
      const msg = policy.customRestrictionMessage || "Your email domain is not authorized for this institution-restricted event.";
      return {
        allowed: false,
        reason: msg,
      };
    }

    return { allowed: true };
  }

  if (policy.policyType === "INVITE_ONLY") {
    return {
      allowed: false,
      reason: policy.customRestrictionMessage || "This event is strictly invite-only.",
    };
  }

  return { allowed: true };
}
