/**
 * Background Job & BullMQ Queue Type Definitions
 * Strict types for payloads, deterministic job naming, retry policies, and DLQ handling.
 */

export enum QueueName {
  RESERVATION_EXPIRY = "reservation-expiry",
  EMAIL = "email",
  NOTIFICATION = "notification",
  WEBHOOK = "webhook",
  PAYMENT_RECONCILIATION = "payment-reconciliation",
  ANALYTICS = "analytics",
}

export const ALL_QUEUE_NAMES: QueueName[] = [
  QueueName.RESERVATION_EXPIRY,
  QueueName.EMAIL,
  QueueName.NOTIFICATION,
  QueueName.WEBHOOK,
  QueueName.PAYMENT_RECONCILIATION,
  QueueName.ANALYTICS,
];

export const QUEUE_NAMESPACE_PREFIX = "happenins:queue";

/**
 * Helper to generate deterministic job IDs for idempotency
 */
export const JobIdGenerators = {
  reservationExpiry: (bookingId: string) => `reservation-expiry:${bookingId.trim()}`,
  reservationScan: (timestamp: number) => `reservation-expiry-scan:${timestamp}`,
  email: (messageId: string) => `email:${messageId.trim()}`,
  notification: (userId: string, refId: string) => `notification:${userId.trim()}:${refId.trim()}`,
  webhook: (eventId: string) => `webhook:${eventId.trim()}`,
  paymentReconciliation: (paymentId: string) => `payment-recon:${paymentId.trim()}`,
  paymentScan: (timestamp: number) => `payment-recon-scan:${timestamp}`,
  analytics: (eventId: string, metricType: string, dateStr: string) => `analytics:${eventId.trim()}:${metricType}:${dateStr}`,
};

// 1. Reservation Expiry Job Data
export interface ReservationExpiryJobData {
  bookingId?: string;
  scanAll?: boolean;
  triggerSource?: "checkout_abandon" | "cron_sweep" | "manual_admin" | "timeout";
  timestamp?: number;
}

// 2. Transactional Email Job Data
export interface EmailJobData {
  to: string;
  subject: string;
  body: string;
  html?: string;
  messageId: string; // Unique deterministic identifier for email idempotency
  template?: string;
  metadata?: Record<string, any>;
}

// 3. Notification Job Data
export interface NotificationJobData {
  userId: string;
  title: string;
  message: string;
  channel?: "IN_APP" | "PUSH" | "SMS";
  metadata?: Record<string, any>;
  idempotencyKey?: string;
}

// 4. Webhook Processing Job Data
export interface WebhookJobData {
  eventId: string;
  eventType: string;
  payload: Record<string, any>;
  receivedAt: string;
}

// 5. Payment Reconciliation Job Data
export interface PaymentReconciliationJobData {
  paymentId?: string;
  bookingId?: string;
  scanStale?: boolean;
  olderThanMinutes?: number;
  razorpayPaymentId?: string;
}

// 6. Analytics Aggregation Job Data
export interface AnalyticsJobData {
  eventId: string;
  metricType: "SALES" | "PAGE_VIEW" | "CHECK_IN" | "DAILY_ROLLUP";
  data?: Record<string, any>;
  dateStr?: string;
}

export type AnyJobData =
  | ReservationExpiryJobData
  | EmailJobData
  | NotificationJobData
  | WebhookJobData
  | PaymentReconciliationJobData
  | AnalyticsJobData;

export interface JobEnqueueOptions {
  jobId?: string;
  idempotencyKey?: string;
  delayMs?: number;
  attempts?: number;
  backoffMs?: number;
  priority?: number;
  removeOnComplete?: boolean | number | { age?: number; count?: number };
  removeOnFail?: boolean | number | { age?: number; count?: number };
}

export interface DLQJobRecord {
  id: string;
  queue: string;
  name: string;
  data: Record<string, any>;
  failedReason?: string;
  stacktrace?: string[];
  attemptsMade: number;
  timestamp: number;
  processedOn?: number;
  finishedOn?: number;
}

export interface SingleQueueStats {
  waiting: number;
  active: number;
  completed: number;
  failed: number;
  delayed: number;
  paused: boolean;
}

export interface QueueHealthStats {
  isDistributed: boolean;
  mode: "bullmq_redis" | "in_memory_dev_fallback";
  queues: Record<string, SingleQueueStats>;
  totalWaiting: number;
  totalActive: number;
  totalFailed: number;
  totalDelayed: number;
}
