import { getContext, RequestContext } from "./context";

export type LogLevel = "DEBUG" | "INFO" | "WARN" | "ERROR";

export interface LogContext {
  requestId?: string;
  traceId?: string;
  spanId?: string;
  userId?: string;
  eventId?: string;
  bookingId?: string;
  paymentId?: string;
  ticketId?: string;
  path?: string;
  method?: string;
  statusCode?: number;
  durationMs?: number;
  errorCode?: string;
  code?: string;
  stack?: string;
  service?: string;
  httpRequest?: {
    requestMethod?: string;
    requestUrl?: string;
    requestSize?: number | string;
    status?: number;
    responseSize?: number | string;
    userAgent?: string;
    remoteIp?: string;
    latency?: string;
    protocol?: string;
  };
  [key: string]: any;
}

const SENSITIVE_KEY_PATTERNS = [
  "password",
  "passwordhash",
  "token",
  "refreshtoken",
  "jwt",
  "secret",
  "razorpaysignature",
  "razorpaykeysecret",
  "razorpaywebhooksecret",
  "authorization",
  "cookie",
  "set-cookie",
  "qrhash",
  "qrtoken",
  "signature",
  "codeverifier",
  "codechallenge",
  "card",
  "cvv",
  "cvc",
  "smtp_pass",
  "smtppass",
  "apppassword",
  "pass",
  "bankaccountnumber",
  "taxid",
  "privatekey",
  "private_key",
  "accesstoken",
  "id_token",
  "pin",
  "apikey",
  "api_key",
  "credential",
  "secret_key",
  "session_id",
];

export function sanitizeString(text: string): string {
  if (!text || typeof text !== "string") return text;
  return text
    .replace(/((?:postgres(?:ql)?|redis|mongodb(?:\+srv)?):\/\/[^:\s]+:)([^@\s]+)(@)/gi, "$1[REDACTED]$3")
    .replace(/(Bearer\s+)[A-Za-z0-9._~+/-]+=*/gi, "$1[REDACTED]")
    .replace(/((?:password|pass|smtp_pass|secret)\s*[:=]\s*["']?)([^"',\s]+)(["']?)/gi, "$1[REDACTED]$3");
}

export function sanitize(obj: any, seen = new WeakSet()): any {
  if (typeof obj === "string") return sanitizeString(obj);
  if (!obj || typeof obj !== "object") return obj;
  if (seen.has(obj)) return "[CIRCULAR]";
  seen.add(obj);

  if (Array.isArray(obj)) {
    return obj.map((item) => sanitize(item, seen));
  }

  const sanitized: Record<string, any> = {};
  for (const [key, value] of Object.entries(obj)) {
    const lowerKey = key.toLowerCase();
    const isSensitive = SENSITIVE_KEY_PATTERNS.some((pattern) => lowerKey.includes(pattern));

    if (isSensitive) {
      sanitized[key] = "[REDACTED]";
    } else if (typeof value === "object" && value !== null) {
      sanitized[key] = sanitize(value, seen);
    } else if (typeof value === "string") {
      sanitized[key] = sanitizeString(value);
    } else {
      sanitized[key] = value;
    }
  }
  return sanitized;
}

const GCP_PROJECT_ID = process.env.GOOGLE_CLOUD_PROJECT || process.env.GCP_PROJECT;

function mapSeverity(level: LogLevel): string {
  switch (level) {
    case "DEBUG":
      return "DEBUG";
    case "INFO":
      return "INFO";
    case "WARN":
      return "WARNING";
    case "ERROR":
      return "ERROR";
    default:
      return "DEFAULT";
  }
}

function formatLog(level: LogLevel, message: string, context?: LogContext): string {
  const isProd = process.env.NODE_ENV === "production";
  const timestamp = new Date().toISOString();
  const currentContext = getContext();

  const mergedContext: LogContext = {
    service: process.env.SERVICE_NAME || "happenins-api",
    processType: process.env.PROCESS_TYPE || "combined",
    environment: process.env.NODE_ENV || "development",
    requestId: currentContext?.requestId,
    traceId: currentContext?.traceId,
    spanId: currentContext?.spanId,
    userId: currentContext?.userId,
    path: currentContext?.path,
    method: currentContext?.method,
    ...(context || {}),
  };

  const cleanCtx = sanitize(mergedContext);
  const cleanMessage = sanitizeString(message);

  if (isProd) {
    const gcpTrace = GCP_PROJECT_ID && cleanCtx.traceId
      ? `projects/${GCP_PROJECT_ID}/traces/${cleanCtx.traceId}`
      : cleanCtx.traceId;

    const payload: Record<string, any> = {
      severity: mapSeverity(level),
      timestamp,
      message: cleanMessage,
      serviceContext: {
        service: cleanCtx.service,
        version: process.env.K_REVISION || "1.0.0",
      },
      ...cleanCtx,
    };

    if (gcpTrace) {
      payload["logging.googleapis.com/trace"] = gcpTrace;
    }
    if (cleanCtx.spanId) {
      payload["logging.googleapis.com/spanId"] = cleanCtx.spanId;
    }

    return JSON.stringify(payload);
  } else {
    const ctxEntries = Object.entries(cleanCtx).filter(
      ([k]) => !["service", "environment", "processType"].includes(k)
    );
    const ctxString = ctxEntries.length > 0 ? ` ${JSON.stringify(Object.fromEntries(ctxEntries))}` : "";
    return `[${level}] [${timestamp}] ${cleanMessage}${ctxString}`;
  }
}

export class StructuredLogger {
  private baseContext: LogContext;

  constructor(baseContext: LogContext = {}) {
    this.baseContext = baseContext;
  }

  public child(childContext: LogContext): StructuredLogger {
    return new StructuredLogger({ ...this.baseContext, ...childContext });
  }

  public debug(message: string, context?: LogContext): void {
    if (process.env.LOG_LEVEL === "debug" || process.env.NODE_ENV !== "production") {
      console.debug(formatLog("DEBUG", message, { ...this.baseContext, ...context }));
    }
  }

  public info(message: string, context?: LogContext): void {
    console.log(formatLog("INFO", message, { ...this.baseContext, ...context }));
  }

  public warn(message: string, context?: LogContext): void {
    console.warn(formatLog("WARN", message, { ...this.baseContext, ...context }));
  }

  public error(message: string, context?: LogContext): void {
    console.error(formatLog("ERROR", message, { ...this.baseContext, ...context }));
  }

  public http(message: string, context?: LogContext): void {
    console.log(formatLog("INFO", message, { ...this.baseContext, ...context }));
  }

  public audit(message: string, context?: LogContext): void {
    console.log(formatLog("INFO", message, { ...this.baseContext, audit: true, ...context }));
  }
}

export const logger = new StructuredLogger();
