import { getEnv } from "./env";

export interface DatabaseConfig {
  url: string;
  multiplexedUrl: string;
  poolMode: "transaction";
  pgbouncer: boolean;
  maxConnections: number;
  connectionTimeoutMs: number;
  idleTimeoutMs: number;
  statementTimeoutMs: number;
  poolTimeoutSeconds: number;
}

/**
 * Builds a PgBouncer Transaction-Mode multiplexed PostgreSQL connection URL.
 *
 * In standard Node.js setups, 50 Express server pods with 20 connections each = 1,000 connections,
 * crashing PostgreSQL.
 *
 * In PgBouncer Transaction Pooling Mode:
 * - Thousands of incoming client requests share a pool of just 20 to 50 physical connections.
 * - Connections are assigned only for the milliseconds a query/transaction executes, then immediately returned.
 * - 'pgbouncer=true' instructs Prisma to avoid server-side prepared statements that conflict with transaction mode.
 * - 'connection_limit=5' restricts each pod so 50 pods only consume a total of 250 multiplexed client slots.
 * - 'options=-c statement_timeout=3000ms' strictly terminates any query running longer than 3 seconds.
 */
export function buildMultiplexedDatabaseUrl(
  rawUrl: string,
  options: {
    connectionLimit?: number;
    poolTimeoutSeconds?: number;
    statementTimeoutMs?: number;
    forcePgbouncer?: boolean;
  } = {}
): string {
  try {
    const url = new URL(rawUrl);

    // 1. Transaction pooling compatibility (Prisma specific flag)
    url.searchParams.set("pgbouncer", "true");

    // 2. Multiplexed connection limits per pod (default 5, max 10)
    const limit = options.connectionLimit || 5;
    url.searchParams.set("connection_limit", String(limit));

    // 3. Fast pool checkout timeout (10 seconds)
    const poolTimeout = options.poolTimeoutSeconds || 10;
    url.searchParams.set("pool_timeout", String(poolTimeout));

    // 4. Fast connect timeout (5 seconds)
    url.searchParams.set("connect_timeout", "5");

    // 5. Resilient statement timeout (8000ms) to accommodate cross-region network latency while protecting pool
    const statementTimeout = options.statementTimeoutMs || 8000;
    const existingOptions = url.searchParams.get("options") || "";
    if (!existingOptions.includes("statement_timeout")) {
      const combinedOptions = existingOptions
        ? `${existingOptions} -c statement_timeout=${statementTimeout}ms`
        : `-c statement_timeout=${statementTimeout}ms`;
      url.searchParams.set("options", combinedOptions);
    }

    return url.toString();
  } catch {
    // If URL parsing fails, return raw
    return rawUrl;
  }
}

export function getDatabaseConfig(): DatabaseConfig {
  const env = getEnv();
  const rawUrl = env.DATABASE_URL;

  // Resilient statement timeout: 3000ms in test suite, 8000ms in cloud production
  const statementTimeoutMs = env.NODE_ENV === "test" ? 3000 : (Number(process.env.DB_STATEMENT_TIMEOUT_MS) || 8000);
  // Pod connection limit: 5 (50 pods * 5 = 250 multiplexed connections into 20-50 physical PG connections)
  const maxConnections = env.DB_CONNECTION_LIMIT || 5;
  const poolTimeoutSeconds = env.DB_POOL_TIMEOUT_SECONDS || 10;

  const multiplexedUrl = buildMultiplexedDatabaseUrl(rawUrl, {
    connectionLimit: maxConnections,
    poolTimeoutSeconds,
    statementTimeoutMs,
    forcePgbouncer: true,
  });

  return {
    url: rawUrl,
    multiplexedUrl,
    poolMode: "transaction",
    pgbouncer: true,
    maxConnections,
    connectionTimeoutMs: 5000,
    idleTimeoutMs: 10000,
    statementTimeoutMs,
    poolTimeoutSeconds,
  };
}
