import type { NextFunction, Request, Response } from "express";
import { FeatureKey, isFeatureEnabled } from "../config/features";

/**
 * Which endpoints belong to which feature. One table, one middleware: a disabled feature's endpoints answer
 * 404 (as if they did not exist) with a machine-readable code. Paths are relative to the API mount (/api, /api/v1).
 * `:param` segments match any single path segment. A missing method means every method.
 */
export const FEATURE_ROUTES: ReadonlyArray<readonly [FeatureKey, string | undefined, string]> = [
  ["SELF_REGISTRATION", "POST", "/auth/register"],
  ["SELF_REGISTRATION", "POST", "/auth/register/verify"],
  ["PASSWORD_LOGIN", "POST", "/auth/login"],
  ["OTP_LOGIN", "POST", "/auth/otp/send"],
  ["OTP_LOGIN", "POST", "/auth/otp/verify"],
  ["GOOGLE_LOGIN", "GET", "/auth/google/url"],
  ["GOOGLE_LOGIN", "POST", "/auth/google/callback"],
  ["PASSWORD_RESET", "POST", "/auth/forgot-password"],
  ["PASSWORD_RESET", "POST", "/auth/reset-password"],
  ["ORGANIZER_ONBOARDING", "POST", "/auth/onboard"],
  ["ACCOUNT_DELETION", "DELETE", "/auth/profile"],

  ["PAYMENTS", "POST", "/webhooks/razorpay"],
  ["SPLIT_BOOKING", "POST", "/bookings/:bookingId/split-shares/:shareId/pay"],
  ["WALLET", "GET", "/wallet"],
  ["WALLET", "POST", "/bookings/:bookingId/wallet/apply"],
  ["WALLET", "POST", "/bookings/:bookingId/wallet/remove"],
  ["PROMO_CODES", "POST", "/bookings/:bookingId/promo/validate"],
  ["PROMO_CODES", "POST", "/bookings/:bookingId/promo/apply"],
  ["PROMO_CODES", undefined, "/events/:eventId/promo-codes"],
  ["PROMO_CODES", "DELETE", "/promo-codes/:id"],
  ["TICKET_TRANSFERS", "POST", "/tickets/:id/transfer"],
  ["TICKET_TRANSFERS", "POST", "/bookings/:id/transfer"],
  ["TICKET_TRANSFERS", undefined, "/transfers/my-transfers"],
  ["TICKET_TRANSFERS", undefined, "/transfers/:code"],
  ["TICKET_TRANSFERS", undefined, "/transfers/:code/claim"],
  ["TICKET_TRANSFERS", undefined, "/transfers/:id/cancel"],
  ["SEATING_PLANS", "GET", "/events/:eventId/occupied-seats"],
  ["INSTITUTION_ACCESS", undefined, "/institutions"],
  ["INSTITUTION_ACCESS", undefined, "/institutions/check-domain"],
  ["INSTITUTION_ACCESS", undefined, "/institutions/otp/send"],
  ["INSTITUTION_ACCESS", undefined, "/institutions/otp/verify"],
  ["INSTITUTION_ACCESS", undefined, "/institutions/otp/status"],
  ["WAITING_ROOM", undefined, "/queue/enter"],
  ["WAITING_ROOM", undefined, "/queue/leave"],
  ["WAITING_ROOM", undefined, "/queue/status"],

  ["STAFF_SCANNERS", undefined, "/staff-scanners/login"],
  ["STAFF_SCANNERS", undefined, "/staff-scanners/scan"],
  ["STAFF_SCANNERS", undefined, "/organizer/events/:eventId/staff-scanners"],
  ["STAFF_SCANNERS", undefined, "/organizer/staff-scanners/:id"],
  ["EVENT_EXPORT", "GET", "/organizer/events/:eventId/export"],
  ["REVIEWS", undefined, "/events/:eventId/reviews"],
  ["REVIEWS", "GET", "/events/:eventId/review-eligibility"],
  ["WHATSAPP_DELIVERY", "GET", "/bookings/:id/whatsapp"],
  ["WHATSAPP_DELIVERY", "POST", "/bookings/:id/send-whatsapp"],
  ["DEV_EMAIL_INBOX", undefined, "/emails"],
  ["DEV_EMAIL_INBOX", undefined, "/emails/test"],
];

const compiled = FEATURE_ROUTES.map(([feature, method, pattern]) => ({
  feature,
  method,
  regex: new RegExp(`^${pattern.replace(/:[A-Za-z]+/g, "[^/]+")}/?$`),
}));

export function featureForRoute(method: string, path: string): FeatureKey | undefined {
  return compiled.find((r) => (!r.method || r.method === method.toUpperCase()) && r.regex.test(path))?.feature;
}

export function featureGate(req: Request, res: Response, next: NextFunction) {
  const feature = featureForRoute(req.method, req.path);
  if (feature && !isFeatureEnabled(feature)) {
    return res.status(404).json({ error: "Not found", code: "FEATURE_DISABLED", feature });
  }
  next();
}
