import { Request, Response, NextFunction } from "express";
import crypto from "crypto";
import { runWithContext, RequestContext } from "../utils/context";

export function tracingMiddleware(req: Request, res: Response, next: NextFunction): void {
  // 1. Request ID (either client-provided or fresh UUID)
  const incomingReqId = req.headers["x-request-id"] as string;
  const requestId = incomingReqId && incomingReqId.trim().length > 0
    ? incomingReqId.trim()
    : crypto.randomUUID();

  // 2. Google Cloud Trace / W3C Trace Context extraction
  let traceId: string | undefined;
  let spanId: string | undefined;

  const gcpTraceHeader = req.headers["x-cloud-trace-context"] as string;
  const w3cTraceHeader = req.headers["traceparent"] as string;

  if (gcpTraceHeader) {
    // Format: TRACE_ID/SPAN_ID;o=TRACE_TRUE
    const match = gcpTraceHeader.match(/^([a-f0-9]+)(?:\/([a-f0-9]+))?(?:;o=([01]))?/i);
    if (match) {
      traceId = match[1];
      spanId = match[2];
    }
  } else if (w3cTraceHeader) {
    // Format: 00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01
    const match = w3cTraceHeader.match(/^00-([a-f0-9]{32})-([a-f0-9]{16})-([a-f0-9]{2})$/i);
    if (match) {
      traceId = match[1];
      spanId = match[2];
    }
  }

  // Fallback trace ID if none supplied
  if (!traceId) {
    traceId = crypto.randomBytes(16).toString("hex");
  }

  // Attach to Express request object
  req.id = requestId;
  req.traceId = traceId;
  req.spanId = spanId;

  // Set response headers for client tracing correlation
  res.setHeader("X-Request-Id", requestId);
  if (traceId) {
    res.setHeader("X-Trace-Id", traceId);
  }

  const context: RequestContext = {
    requestId,
    traceId,
    spanId,
    ipAddress: req.ip || (req.socket ? req.socket.remoteAddress : undefined),
    userAgent: req.headers["user-agent"] as string,
    path: req.path,
    method: req.method,
    startTime: Date.now(),
  };

  runWithContext(context, () => {
    next();
  });
}
