import { getEnv } from "./env";

export interface RedisConfig {
  url?: string;
  enabled: boolean;
  connectTimeoutMs: number;
  maxRetries: number;
  keyPrefix: string;
}

/**
 * Normalizes user or environment provided Redis connection strings.
 * Handles:
 * - Direct URLs: redis://..., rediss://...
 * - CLI commands: "redis-cli --tls -u redis://..." or "redis-cli -u ..."
 * - Upstash / TLS auto-detection (e.g. upstash.io hosts require TLS -> rediss://)
 * - Raw hosts: "host:port" -> "redis://host:port"
 */
export function normalizeRedisUrl(rawUrl?: string): string {
  if (!rawUrl) return "";
  let str = rawUrl.trim();

  // Handle accidental quotes around string
  if ((str.startsWith('"') && str.endsWith('"')) || (str.startsWith("'") && str.endsWith("'"))) {
    str = str.slice(1, -1).trim();
  }

  const hasTlsFlag = str.includes("--tls") || str.includes("-tls");

  // Extract from CLI command if provided like: redis-cli --tls -u redis://...
  const uMatch = str.match(/-u\s+([^\s]+)/);
  if (uMatch) {
    str = uMatch[1].trim();
  } else if (str.startsWith("redis-cli")) {
    const parts = str.split(/\s+/);
    const urlPart = parts.find((p) => p.startsWith("redis://") || p.startsWith("rediss://"));
    if (urlPart) {
      str = urlPart;
    }
  }

  // If missing protocol but contains host:port
  if (!str.startsWith("redis://") && !str.startsWith("rediss://") && str.length > 0) {
    if (hasTlsFlag || str.includes("upstash.io")) {
      str = `rediss://${str}`;
    } else {
      str = `redis://${str}`;
    }
  }

  // If --tls was specified or host is upstash.io and protocol is redis://, upgrade to rediss://
  if ((hasTlsFlag || str.includes("upstash.io")) && str.startsWith("redis://")) {
    str = `rediss://${str.slice("redis://".length)}`;
  }

  return str;
}

export function getRedisConfig(): RedisConfig {
  const env = getEnv();
  const rawUrl = (process.env.REDIS_URL || env.REDIS_URL || "").trim();
  const normalizedUrl = normalizeRedisUrl(rawUrl);
  
  // If explicitly disabled (e.g. REDIS_ENABLED="false" or 0)
  const isExplicitlyDisabled =
    env.REDIS_ENABLED === false ||
    process.env.REDIS_ENABLED === "false" ||
    process.env.REDIS_ENABLED === "0";

  // Detect test runner environment
  const isTest =
    process.env.NODE_ENV === "test" ||
    env.NODE_ENV === "test" ||
    typeof process.env.VITEST !== "undefined" ||
    typeof (globalThis as any).__vitest_environment__ !== "undefined";

  // If a remote Redis URL is provided (e.g. rediss://... or non-localhost/non-127.0.0.1)
  const isRemoteUrl =
    normalizedUrl.length > 0 &&
    !normalizedUrl.includes("localhost") &&
    !normalizedUrl.includes("127.0.0.1");

  // Enabled only when not explicitly disabled, not running tests without a remote Redis,
  // and either a remote URL is present or explicit REDIS_ENABLED is set with a non-empty URL
  const isEnabled =
    !isExplicitlyDisabled &&
    !isTest &&
    (isRemoteUrl || (normalizedUrl.length > 0 && (env.REDIS_ENABLED === true || process.env.REDIS_ENABLED === "true")));

  return {
    url: normalizedUrl || "redis://localhost:6379",
    enabled: isEnabled,
    connectTimeoutMs: env.REDIS_CONNECT_TIMEOUT_MS || 10000,
    maxRetries: env.REDIS_MAX_RETRIES || 5,
    keyPrefix: "happenins:",
  };
}
