/**
 * Currency and Date Formatting Utilities for India (INR & IST)
 * Single Source of Truth for Indian Standard Time (Asia/Kolkata, UTC+05:30)
 */

/**
 * Formats a given amount into Indian Rupees (₹).
 * Handles cents/paise (divides by 100) or direct rupee values.
 */
export const formatRupees = (amount: number, isCents = true): string => {
  if (amount === 0) return "FREE";
  const val = isCents ? amount / 100 : amount;
  return `₹${val.toLocaleString("en-IN", {
    minimumFractionDigits: val % 1 === 0 ? 0 : 2,
    maximumFractionDigits: 2,
  })}`;
};

/**
 * Returns YYYY-MM-DD string strictly in Indian Standard Time (Asia/Kolkata).
 * Perfect for filenames and date keys.
 */
export const getISTDateString = (dateInput: string | Date | number = new Date()): string => {
  try {
    const d = new Date(dateInput);
    if (isNaN(d.getTime())) return new Date().toISOString().slice(0, 10);
    return new Intl.DateTimeFormat("en-CA", {
      timeZone: "Asia/Kolkata",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(d);
  } catch {
    return new Date().toISOString().slice(0, 10);
  }
};

/**
 * Formats a date string, number, or Date object into Indian Standard Time (IST).
 * Guarantees Asia/Kolkata timezone even if custom options are passed.
 */
export const formatDateIST = (
  dateInput: string | Date | number | null | undefined,
  options?: Intl.DateTimeFormatOptions
): string => {
  if (!dateInput) return "";
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return "";

  const defaultOptions: Intl.DateTimeFormatOptions = {
    weekday: "short",
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  };

  const mergedOptions: Intl.DateTimeFormatOptions = {
    timeZone: "Asia/Kolkata",
    ...(options ? options : defaultOptions),
  };

  // Strictly enforce Asia/Kolkata
  mergedOptions.timeZone = "Asia/Kolkata";

  const formatted = d
    .toLocaleString("en-IN", mergedOptions)
    .replace(/\b(am|pm)\b/i, (m) => m.toUpperCase());

  // If time was requested or default was used, append IST if not already in string
  const hasTime = mergedOptions.hour || mergedOptions.minute || mergedOptions.timeStyle;
  if (hasTime && !formatted.includes("IST")) {
    return `${formatted} IST`;
  }
  return formatted;
};

/**
 * Formats short time in Indian Standard Time (e.g., 07:30 PM IST or 07:30 PM).
 */
export const formatTimeIST = (
  dateInput: string | Date | number | null | undefined,
  includeSeconds = false,
  includeSuffix = true
): string => {
  if (!dateInput) return "";
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return "";

  const opts: Intl.DateTimeFormatOptions = {
    timeZone: "Asia/Kolkata",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  };

  if (includeSeconds) {
    opts.second = "2-digit";
  }

  const timeStr = d
    .toLocaleTimeString("en-IN", opts)
    .replace(/\b(am|pm)\b/i, (m) => m.toUpperCase());

  return includeSuffix ? `${timeStr} IST` : timeStr;
};

/**
 * Formats full Date + Time in Indian Standard Time specifically for CSV ledgers and audit records.
 * Example output: "04/10/2026, 06:30:15 PM IST"
 */
export const formatCSVDateTimeIST = (
  dateInput: string | Date | number | null | undefined
): string => {
  if (!dateInput) return "N/A";
  const d = new Date(dateInput);
  if (isNaN(d.getTime())) return "N/A";

  const dtStr = new Intl.DateTimeFormat("en-IN", {
    timeZone: "Asia/Kolkata",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  })
    .format(d)
    .replace(/\b(am|pm)\b/i, (m) => m.toUpperCase());

  return `${dtStr} IST`;
};
