import { getPrisma } from "../utils/db";

export class StaffScannerRepository {
  private prisma = getPrisma();

  async findById(id: string) {
    return this.prisma.staffScanner.findUnique({
      where: { id },
      include: {
        event: {
          select: {
            id: true,
            title: true,
            slug: true,
            venue: true,
            startsAt: true,
            endsAt: true,
            organizerId: true,
            ticketTiers: {
              select: { id: true, name: true, price: true },
            },
          },
        },
        organizer: true,
      },
    });
  }

  async findByPin(pin: string, eventId?: string) {
    const cleanPin = pin.trim();
    if (eventId) {
      return this.prisma.staffScanner.findFirst({
        where: {
          pin: cleanPin,
          eventId,
          isActive: true,
        },
        include: {
          event: {
            select: {
              id: true,
              title: true,
              slug: true,
              venue: true,
              startsAt: true,
              endsAt: true,
              organizerId: true,
              ticketTiers: {
                select: { id: true, name: true, price: true },
              },
            },
          },
        },
      });
    }

    // Find any active staff scanner matching this PIN across active events
    return this.prisma.staffScanner.findFirst({
      where: {
        pin: cleanPin,
        isActive: true,
      },
      include: {
        event: {
          select: {
            id: true,
            title: true,
            slug: true,
            venue: true,
            startsAt: true,
            endsAt: true,
            organizerId: true,
            ticketTiers: {
              select: { id: true, name: true, price: true },
            },
          },
        },
      },
      orderBy: { createdAt: "desc" },
    });
  }

  /** PINs of every active scanner on any event. PINs must be unique across events so a PIN-only login is unambiguous. */
  async findAllActivePins(): Promise<Set<string>> {
    const rows = await this.prisma.staffScanner.findMany({ where: { isActive: true }, select: { pin: true } });
    return new Set(rows.map((r) => r.pin));
  }

  /** Number of active scanners sharing this PIN (used to refuse ambiguous PIN-only logins). */
  async countActiveByPin(pin: string): Promise<number> {
    return this.prisma.staffScanner.count({ where: { pin: pin.trim(), isActive: true } });
  }

  async findByEventId(eventId: string) {
    return this.prisma.staffScanner.findMany({
      where: { eventId },
      include: {
        event: {
          select: {
            id: true,
            title: true,
            slug: true,
            venue: true,
            startsAt: true,
            endsAt: true,
          },
        },
      },
      orderBy: [
        { gateName: "asc" },
        { createdAt: "desc" },
      ],
    });
  }

  async create(data: {
    eventId: string;
    organizerId: string;
    staffName: string;
    pin: string;
    gateName: string;
    allowedTiers?: string;
    expiresAt?: Date | null;
    notes?: string;
  }) {
    return this.prisma.staffScanner.create({
      data: {
        eventId: data.eventId,
        organizerId: data.organizerId,
        staffName: data.staffName,
        pin: data.pin,
        gateName: data.gateName,
        allowedTiers: data.allowedTiers || "ALL",
        expiresAt: data.expiresAt || null,
        notes: data.notes || null,
      },
      include: {
        event: {
          select: {
            id: true,
            title: true,
            slug: true,
            venue: true,
            startsAt: true,
            endsAt: true,
          },
        },
      },
    });
  }

  async createMany(
    items: Array<{
      eventId: string;
      organizerId: string;
      staffName: string;
      pin: string;
      gateName: string;
      allowedTiers?: string;
      expiresAt?: Date | null;
      notes?: string;
    }>
  ) {
    const created: any[] = [];
    for (const item of items) {
      const rec = await this.prisma.staffScanner.create({
        data: {
          eventId: item.eventId,
          organizerId: item.organizerId,
          staffName: item.staffName,
          pin: item.pin,
          gateName: item.gateName,
          allowedTiers: item.allowedTiers || "ALL",
          expiresAt: item.expiresAt || null,
          notes: item.notes || null,
        },
        include: {
          event: {
            select: {
              id: true,
              title: true,
              slug: true,
              venue: true,
              startsAt: true,
              endsAt: true,
            },
          },
        },
      });
      created.push(rec);
    }
    return created;
  }

  async update(
    id: string,
    data: {
      staffName?: string;
      gateName?: string;
      allowedTiers?: string;
      isActive?: boolean;
      pin?: string;
      expiresAt?: Date | null;
      notes?: string | null;
    }
  ) {
    return this.prisma.staffScanner.update({
      where: { id },
      data,
      include: {
        event: {
          select: {
            id: true,
            title: true,
            slug: true,
            venue: true,
            startsAt: true,
            endsAt: true,
          },
        },
      },
    });
  }

  async delete(id: string) {
    return this.prisma.staffScanner.delete({
      where: { id },
    });
  }

  async incrementScanCount(id: string) {
    return this.prisma.staffScanner.update({
      where: { id },
      data: {
        scansCount: { increment: 1 },
        lastScannedAt: new Date(),
      },
    });
  }

  async getGateStats(eventId: string) {
    const staffScanners = await this.prisma.staffScanner.findMany({
      where: { eventId },
      orderBy: { scansCount: "desc" },
    });

    const attendanceLogs = await this.prisma.attendanceLog.findMany({
      where: {
        eventId,
        scanOutcome: "SUCCESS",
      },
      select: {
        id: true,
        gateName: true,
        scannedAt: true,
        staffScannerId: true,
      },
    });

    return {
      staffScanners,
      attendanceLogs,
    };
  }
}
