import { errorMessage } from "../utils/error-message";
const bookingItemSchema = z.object({
  ticketTierId: z.string().min(1, "Invalid ticket tier ID format"),
  quantity: z.number().int().min(1, "Quantity must be at least 1"),
  seatNumbers: z.string().optional(),
});

const reserveSchema = z.object({
  eventId: z.string().min(1, "Invalid event ID format"),
  items: z.array(bookingItemSchema).min(1, "Must reserve at least 1 ticket"),
  isSplitBooking: z.boolean().optional(),
  splitShares: z.array(z.object({
    friendName: z.string().min(1, "Friend name is required"),
    email: z.string().email("Invalid friend email format"),
    amount: z.number().int().min(1, "Split share amount must be valid"),
  })).optional(),
  verificationToken: z.string().optional(),
  collegeEmail: z.string().optional(),
  admissionToken: z.string().optional(),
});

const confirmSchema = z.object({
  bookingId: z.string().min(1, "Invalid booking ID format"),
  transactionId: z.string().min(1, "Transaction reference required"),
  method: z.string().default("CARD"),
  razorpayPaymentId: z.string().optional(),
  razorpayOrderId: z.string().optional(),
  razorpaySignature: z.string().optional(),
});

const scanSchema = z.object({
  qrHash: z.string().min(4, "Invalid QR string format"),
});

