import Redis, { RedisOptions } from "ioredis";
import crypto from "crypto";
import { getRedisConfig } from "../config/redis";
import { logger } from "./logger";
import { metrics } from "./metrics";
import { errorMessage } from "./error-message";

let redisClient: Redis | null = null;
let isConnected = false;
let isConnecting = false;
let connectionFailedPermanently = false;

function maskRedisUrl(url?: string): string {
  if (!url) return "N/A";
  try {
    const parsed = new URL(url);
    if (parsed.password) {
      parsed.password = "******";
    }
    return parsed.toString();
  } catch {
    return url.replace(/:\/\/[^@]+@/, "://***:***@");
  }
}

export function initRedis(): Redis | null {
  const config = getRedisConfig();

  if (!config.enabled) {
    logger.info("Redis is disabled via configuration. Operating in process-local / PostgreSQL fallback mode.");
    return null;
  }

  if (redisClient) {
    return redisClient;
  }

  if (isConnecting || connectionFailedPermanently) {
    return redisClient;
  }

  try {
    isConnecting = true;
    const maskedUrl = maskRedisUrl(config.url);
    logger.info(`Initializing Redis connection to ${maskedUrl}...`);

    const redisOptions: RedisOptions = {
      connectTimeout: config.connectTimeoutMs,
      maxRetriesPerRequest: 3,
      enableReadyCheck: true,
      retryStrategy: (times: number) => {
        if (times > config.maxRetries) {
          logger.warn(`Redis connection failed after ${times} attempts. Switching to safe fallback mode.`);
          connectionFailedPermanently = true;
          return null; // Stop retrying automatically
        }
        const delay = Math.min(times * 500, 3000);
        logger.warn(`Redis connection retry #${times} in ${delay}ms...`);
        return delay;
      },
      lazyConnect: true,
    };

    redisClient = new Redis(config.url || "redis://localhost:6379", redisOptions);

    redisClient.on("connect", () => {
      isConnected = true;
      connectionFailedPermanently = false;
      logger.info("Redis client connected successfully.");
      metrics.incrementCounter("redis_connections_total", "connected");
    });

    redisClient.on("ready", () => {
      isConnected = true;
      logger.info("Redis client is ready to accept commands.");
    });

    redisClient.on("error", (err) => {
      isConnected = false;
      logger.warn("Redis client encountered a connection error", { message: err.message });
      metrics.incrementCounter("redis_errors_total", "error");
    });

    redisClient.on("close", () => {
      isConnected = false;
      logger.warn("Redis connection closed.");
    });

    // Attempt non-blocking connection
    redisClient.connect().catch((err) => {
      isConnected = false;
      logger.warn("Initial Redis connection attempt failed. Non-critical features will degrade gracefully.", {
        message: err.message,
      });
    });

    return redisClient;
  } catch (err: unknown) {
    isConnected = false;
    logger.error("Failed to instantiate Redis client", { message: errorMessage(err) });
    return null;
  } finally {
    isConnecting = false;
  }
}

export function getRedisClient(): Redis | null {
  if (!redisClient && !connectionFailedPermanently) {
    return initRedis();
  }
  return redisClient;
}

export function isRedisAvailable(): boolean {
  return isConnected && redisClient !== null && redisClient.status === "ready";
}

/**
 * Resolves true once the client is ready, false if it is disabled or not ready within timeoutMs.
 * Used at boot so rate limiters bind to the shared Redis store instead of silently using memory.
 */
export async function waitForRedisReady(timeoutMs = 5000): Promise<boolean> {
  const client = getRedisClient();
  if (!client) return false;
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (isRedisAvailable()) return true;
    await new Promise((r) => setTimeout(r, 100));
  }
  return isRedisAvailable();
}

export async function pingRedis(): Promise<{ status: "ok" | "error"; latencyMs?: number; message?: string }> {
  const client = getRedisClient();
  if (!client || !isConnected) {
    return { status: "error", message: "Redis client is not connected" };
  }

  const start = Date.now();
  try {
    const result = await client.ping();
    const latencyMs = Date.now() - start;
    if (result === "PONG") {
      return { status: "ok", latencyMs };
    }
    return { status: "error", message: `Unexpected ping response: ${result}` };
  } catch (err: unknown) {
    return { status: "error", message: errorMessage(err) };
  }
}

export async function closeRedis(): Promise<void> {
  if (redisClient) {
    logger.info("Closing Redis connection cleanly...");
    try {
      await redisClient.quit();
      logger.info("Redis connection closed cleanly.");
    } catch (err: unknown) {
      logger.warn("Forcing Redis disconnect after quit failure", { message: errorMessage(err) });
      redisClient.disconnect();
    } finally {
      redisClient = null;
      isConnected = false;
    }
  }
}

// Key Namespacing Helpers
export const RedisKeys = {
  idempotency: (scope: string, userId: string, endpoint: string, key: string): string => {
    const cleanEndpoint = endpoint.replace(/[^a-zA-Z0-9_-]/g, "_");
    return `happenins:idempotency:${scope}:${userId}:${cleanEndpoint}:${key.trim()}`;
  },
  cache: (resource: string, identifier: string): string => {
    return `happenins:cache:${resource}:${identifier.trim()}`;
  },
  rateLimit: (scope: string, identifier: string): string => {
    return `happenins:ratelimit:${scope}:${identifier.trim()}`;
  },
  lock: (resource: string, identifier: string): string => {
    return `happenins:lock:${resource}:${identifier.trim()}`;
  },
  queueWaiting: (eventId: string): string => {
    return `happenins:queue:waiting:${eventId.trim()}`;
  },
  queueActive: (eventId: string): string => {
    return `happenins:queue:active:${eventId.trim()}`;
  },
  inventoryTier: (tierId: string): string => {
    return `happenins:inventory:tier:${tierId.trim()}`;
  },
  seatLock: (eventId: string, seatLabel: string): string => {
    return `happenins:lock:seat:${eventId.trim()}:${seatLabel.trim().toUpperCase()}`;
  },
};

/**
 * Deterministically creates a canonical SHA-256 hash of a request
 * ensuring that property ordering differences do not produce false hash mismatches.
 */
export function createCanonicalRequestHash(method: string, path: string, body: any): string {
  const normalizedMethod = method.toUpperCase().trim();
  const normalizedPath = path.toLowerCase().trim();

  let canonicalBodyStr = "";
  if (body && typeof body === "object") {
    canonicalBodyStr = JSON.stringify(sortObjectKeys(body));
  } else if (body !== undefined && body !== null) {
    canonicalBodyStr = String(body);
  }

  const payload = `${normalizedMethod}:${normalizedPath}:${canonicalBodyStr}`;
  return crypto.createHash("sha256").update(payload).digest("hex");
}

function sortObjectKeys(obj: any): any {
  if (obj === null || typeof obj !== "object") {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj.map(sortObjectKeys);
  }
  const sorted: Record<string, any> = {};
  for (const key of Object.keys(obj).sort()) {
    sorted[key] = sortObjectKeys(obj[key]);
  }
  return sorted;
}

/**
 * Creates a dedicated Redis connection configured for BullMQ Queues and Workers.
 * BullMQ requires maxRetriesPerRequest to be null for blocking commands.
 */
export function createBullRedisConnection(clientName: string = "bullmq"): Redis | null {
  const config = getRedisConfig();
  if (!config.enabled) {
    return null;
  }

  try {
    const redisOptions: RedisOptions = {
      connectTimeout: config.connectTimeoutMs,
      maxRetriesPerRequest: null, // Required by BullMQ
      enableReadyCheck: false,    // Recommended by BullMQ
      lazyConnect: false,
      retryStrategy: (times: number) => {
        if (times > config.maxRetries) {
          logger.warn(`BullMQ Redis connection (${clientName}) stopped retrying after ${times} attempts.`);
          return null;
        }
        return Math.min(times * 500, 3000);
      },
    };

    const client = new Redis(config.url || "redis://localhost:6379", redisOptions);

    client.on("error", (err) => {
      logger.warn(`BullMQ Redis (${clientName}) connection error:`, { message: err.message });
    });

    return client;
  } catch (err: unknown) {
    logger.warn(`Failed to create BullMQ Redis connection (${clientName}):`, { message: errorMessage(err) });
    return null;
  }
}

