import { Request, Response, NextFunction } from "express";
import { metrics, normalizeRoute } from "../utils/metrics";
import { logger } from "../utils/logger";
import { updateContext } from "../utils/context";

export function accessLogMiddleware(req: Request, res: Response, next: NextFunction): void {
  // Skip access logging for internal health probes to reduce log noise if configured
  const isHealthProbe = req.path === "/health" || req.path === "/ready";
  const start = Date.now();

  metrics.recordRequestStart();

  // Capture user context if attached later in the pipeline
  const originalEnd = res.end;
  let bytesSent = 0;

  // Intercept chunks to track response size safely
  const originalWrite = res.write;
  const chunkLength = (chunk: unknown): number =>
    Buffer.isBuffer(chunk) ? chunk.length : typeof chunk === "string" ? Buffer.byteLength(chunk) : 0;

  res.write = function (chunk: unknown, ...args: unknown[]): boolean {
    bytesSent += chunkLength(chunk);
    return (originalWrite as (...a: unknown[]) => boolean).apply(res, [chunk, ...args]);
  } as typeof res.write;

  res.end = function (chunk?: unknown, ...args: unknown[]): Response {
    bytesSent += chunkLength(chunk);
    return (originalEnd as (...a: unknown[]) => Response).apply(res, [chunk, ...args]);
  } as typeof res.end;

  res.on("finish", () => {
    metrics.recordRequestEnd();
    const durationMs = Date.now() - start;
    const statusCode = res.statusCode;
    const method = req.method;
    const normalized = normalizeRoute(req.path);

    // Update context with any user authenticated during request
    if (req.user) {
      updateContext({
        userId: req.user.id,
        userRole: req.user.role,
      });
    }

    // 1. Record RED Metrics
    const metricLabels = {
      method,
      route: normalized,
      status_code: String(statusCode),
    };

    metrics.incrementCounter("http_requests_total", metricLabels);
    metrics.observeHistogram("http_request_duration_ms", durationMs, metricLabels);

    if (statusCode === 429) {
      metrics.incrementCounter("rate_limit_hits_total", { route: normalized, method });
    }

    // 2. Emit Structured Access Log
    if (!isHealthProbe || statusCode >= 400) {
      const userAgent = req.headers["user-agent"] || "unknown";
      const remoteIp = req.ip || (req.socket ? req.socket.remoteAddress : "unknown");
      const requestId = req.id;
      const traceId = req.traceId;

      const logPayload = {
        requestId,
        traceId,
        method,
        path: req.path,
        normalizedRoute: normalized,
        statusCode,
        durationMs,
        bytesSent,
        userId: req.user?.id,
        httpRequest: {
          requestMethod: method,
          requestUrl: req.originalUrl || req.url,
          status: statusCode,
          userAgent,
          remoteIp,
          latency: `${(durationMs / 1000).toFixed(6)}s`,
          responseSize: bytesSent,
        },
      };

      const msg = `HTTP ${method} ${req.originalUrl || req.path} ${statusCode} in ${durationMs}ms [${bytesSent}B]`;

      if (statusCode >= 500) {
        logger.error(msg, logPayload);
      } else if (statusCode >= 400) {
        logger.warn(msg, logPayload);
      } else {
        logger.http(msg, logPayload);
      }
    }
  });

  next();
}
