import type { PrismaDb } from "./prisma-db";

export class BookingQueryRepository {
  constructor(private readonly db: PrismaDb) {}

  async findById(bookingId: string) {
    return this.db.booking.findUnique({
      where: { id: bookingId },
      include: {
        event: true,
        user: true,
        items: {
          include: { ticketTier: true },
        },
        payments: true,
        attendance: true,
        tickets: {
          include: {
            ticketTier: true,
            ownerUser: true,
          },
        },
        promoCode: true,
        splitShares: true,
        transfers: {
          include: {
            senderUser: true,
            claimedByUser: true,
            ticket: true,
          },
        },
      },
    });
  }

  async findByIdempotencyKey(idempotencyKey: string) {
    if (!idempotencyKey) return null;
    return this.db.booking.findUnique({
      where: { idempotencyKey },
      include: {
        event: true,
        user: true,
        items: {
          include: { ticketTier: true },
        },
        payments: true,
        attendance: true,
        tickets: true,
        splitShares: true,
      },
    });
  }

  async findByInvoiceNumber(invoiceNumber: string) {
    return this.db.booking.findUnique({
      where: { invoiceNumber },
      include: {
        event: true,
        user: true,
        items: {
          include: { ticketTier: true },
        },
        payments: true,
        attendance: true,
        tickets: true,
        promoCode: true,
        splitShares: true,
      },
    });
  }

  async findByUserId(userId: string) {
    return this.db.booking.findMany({
      where: { userId },
      include: {
        event: true,
        items: {
          include: { ticketTier: true },
        },
        payments: true,
        attendance: true,
        tickets: {
          include: {
            ticketTier: true,
            ownerUser: true,
          },
        },
        promoCode: true,
        splitShares: true,
        transfers: {
          include: {
            senderUser: true,
            claimedByUser: true,
            ticket: true,
          },
        },
      },
      orderBy: { createdAt: "desc" },
    });
  }

  async findByEventId(eventId: string) {
    return this.db.booking.findMany({
      where: { eventId },
      include: {
        user: true,
        items: {
          include: { ticketTier: true },
        },
        payments: true,
        attendance: true,
        tickets: true,
        promoCode: true,
      },
      orderBy: { createdAt: "desc" },
    });
  }

  async getAllConfirmedBookings() {
    return this.db.booking.findMany({
      where: { status: "CONFIRMED" },
      include: {
        event: true,
        user: true,
        items: {
          include: { ticketTier: true },
        },
        tickets: true,
        attendance: true,
        promoCode: true,
      },
      orderBy: { createdAt: "desc" },
      take: 25,
    });
  }
}
