import { Request, Response, NextFunction } from "express";
import { logger } from "../utils/logger";
import { metrics } from "../utils/metrics";
import { bestEffort } from "../utils/best-effort";
import {
  getRedisClient,
  isRedisAvailable,
  RedisKeys,
  createCanonicalRequestHash,
} from "../utils/redis";
import { errorMessage } from "../utils/error-message";

export interface IdempotencyRecord {
  key: string;
  scope: string;
  userId: string;
  endpoint: string;
  requestHash: string;
  status: "PROCESSING" | "COMPLETED" | "FAILED";
  statusCode?: number;
  headers?: Record<string, string>;
  body?: any;
  createdAt: number;
  completedAt?: number;
}

// In-memory fallback LRU store when Redis is offline / in single-instance mode
const localMemoryStore = new Map<string, IdempotencyRecord>();
const MAX_LOCAL_RECORDS = 5000;
const PROCESSING_LOCK_TTL_SEC = 60; // 60-second lease for processing
const COMPLETED_RECORD_TTL_SEC = 24 * 60 * 60; // 24-hour retention for completed results

export async function idempotencyMiddleware(req: Request, res: Response, next: NextFunction) {
  // 1. Only enforce idempotency on mutating HTTP methods
  if (!["POST", "PUT", "PATCH", "DELETE"].includes(req.method)) {
    return next();
  }

  const rawKey = (req.headers["idempotency-key"] || req.headers["x-idempotency-key"]) as string;

  // If no idempotency key is provided, proceed normally without deduplication
  if (!rawKey || typeof rawKey !== "string" || rawKey.trim().length === 0) {
    return next();
  }

  const idempotencyKey = rawKey.trim();
  const userId = req.user?.id || "anon";
  const endpoint = req.path;
  const requestHash = createCanonicalRequestHash(req.method, req.path, req.body);
  const redisKey = RedisKeys.idempotency("api", userId, endpoint, idempotencyKey);

  const redis = getRedisClient();
  const redisActive = isRedisAvailable() && redis !== null;

  try {
    // 2. Check existing record
    let existingRecord: IdempotencyRecord | null = null;

    if (redisActive && redis) {
      const rawData = await redis.get(redisKey);
      if (rawData) {
        try {
          existingRecord = JSON.parse(rawData);
        } catch {
          existingRecord = null;
        }
      }
    } else {
      const local = localMemoryStore.get(redisKey);
      if (local && Date.now() - local.createdAt < COMPLETED_RECORD_TTL_SEC * 1000) {
        existingRecord = local;
      }
    }

    // 3. Handle existing record logic
    if (existingRecord) {
      // Validation rule: Reject the request if the same key is submitted with a different request payload
      if (existingRecord.requestHash !== requestHash) {
        logger.warn("Idempotency key payload mismatch detected", {
          idempotencyKey,
          userId,
          endpoint,
        });
        metrics.incrementCounter("idempotency_conflicts", endpoint);
        return res.status(409).json({
          status: "error",
          code: "IDEMPOTENCY_PAYLOAD_MISMATCH",
          message: "The provided Idempotency-Key was previously used with a different request payload.",
        });
      }

      // If the request is still actively processing on another thread/instance
      if (existingRecord.status === "PROCESSING") {
        const isExpired = Date.now() - existingRecord.createdAt > PROCESSING_LOCK_TTL_SEC * 1000;
        if (!isExpired) {
          logger.info("Concurrent duplicate request detected while operation is still processing", {
            idempotencyKey,
            endpoint,
          });
          metrics.incrementCounter("idempotency_concurrent_blocked", endpoint);
          return res.status(409).json({
            status: "error",
            code: "IDEMPOTENCY_IN_PROGRESS",
            message: "A request with this Idempotency-Key is currently being processed. Please retry shortly.",
          });
        }
      }

      // If previously completed, return cached response directly
      if (existingRecord.status === "COMPLETED" && existingRecord.statusCode && existingRecord.body !== undefined) {
        logger.info("Idempotent replay served from store", {
          idempotencyKey,
          endpoint,
          statusCode: existingRecord.statusCode,
        });
        metrics.incrementCounter("idempotency_hits", endpoint);

        res.setHeader("X-Idempotency-Hit", "true");
        return res.status(existingRecord.statusCode).json(existingRecord.body);
      }
    }

    // 4. Acquire atomic lease for PROCESSING
    const initialRecord: IdempotencyRecord = {
      key: idempotencyKey,
      scope: "api",
      userId,
      endpoint,
      requestHash,
      status: "PROCESSING",
      createdAt: Date.now(),
    };

    if (redisActive && redis) {
      // Use atomic SET with NX (set only if not exists) and EX (expire in seconds)
      const acquired = await redis.set(
        redisKey,
        JSON.stringify(initialRecord),
        "EX",
        PROCESSING_LOCK_TTL_SEC,
        "NX"
      );

      if (!acquired) {
        // Lost race condition to a concurrent request
        logger.info("Lost atomic race for idempotency key lease", { idempotencyKey, endpoint });
        metrics.incrementCounter("idempotency_concurrent_blocked", endpoint);
        return res.status(409).json({
          status: "error",
          code: "IDEMPOTENCY_IN_PROGRESS",
          message: "A request with this Idempotency-Key is currently processing.",
        });
      }
    } else {
      if (localMemoryStore.size >= MAX_LOCAL_RECORDS) {
        const firstKey = localMemoryStore.keys().next().value;
        if (firstKey) localMemoryStore.delete(firstKey);
      }
      localMemoryStore.set(redisKey, initialRecord);
    }

    // 5. Intercept response completion to save final payload
    const originalJson = res.json.bind(res);

    res.json = function (body: any) {
      const statusCode = res.statusCode;

      // Only store completed results for successful (2xx) or valid business rejection (4xx except 429/5xx)
      if (statusCode >= 200 && statusCode < 500 && statusCode !== 429) {
        const completedRecord: IdempotencyRecord = {
          ...initialRecord,
          status: "COMPLETED",
          statusCode,
          body,
          completedAt: Date.now(),
        };

        if (redisActive && redis) {
          redis
            .set(redisKey, JSON.stringify(completedRecord), "EX", COMPLETED_RECORD_TTL_SEC)
            .catch((err) => {
              logger.warn("Failed to persist completed idempotency record to Redis", {
                message: err.message,
              });
            });
        } else {
          localMemoryStore.set(redisKey, completedRecord);
        }
      } else {
        // On 5xx server errors or transient 429s, delete lock so user can retry safely
        if (redisActive && redis) {
          redis.del(redisKey).catch(bestEffort("redis.del"));
        } else {
          localMemoryStore.delete(redisKey);
        }
      }

      return originalJson(body);
    };

    next();
  } catch (err: unknown) {
    logger.error("Error executing idempotency middleware", {
      idempotencyKey,
      endpoint,
      message: errorMessage(err),
    });
    // In event of catastrophic middleware error, fail safe to next()
    next();
  }
}
