import { getEnv } from "./env";
import { isFeatureEnabled } from "./features";
import { ForbiddenError } from "../errors/app-error";

/** Paid tickets are enabled by default outside production (Razorpay test mode) and off in production unless opted in. */
export function arePaymentsEnabled(): boolean {
  getEnv(); // runs the production boot guards (e.g. a real webhook secret when payments are on)
  return isFeatureEnabled("PAYMENTS");
}

export function assertPaymentsEnabled(): void {
  if (!arePaymentsEnabled()) {
    throw new ForbiddenError("Paid tickets are not enabled on this deployment. Only free tickets are available.");
  }
}

/** Rejects any priced tier when payments are disabled. Prices are in paise. */
export function assertTiersAllowed(tiers: Array<{ price?: number }> | undefined): void {
  if (!arePaymentsEnabled() && (tiers || []).some((t) => (t.price ?? 0) > 0)) {
    throw new ForbiddenError("Paid ticket tiers are not enabled on this deployment. Set every tier price to 0.");
  }
}

export interface PaymentConfig {
  razorpayKeyId: string;
  razorpayKeySecret: string;
  razorpayWebhookSecret: string;
  currency: string;
  reservationHoldMinutes: number;
}

export function getPaymentConfig(): PaymentConfig {
  const env = getEnv();

  return {
    razorpayKeyId: env.RAZORPAY_KEY_ID || "rzp_test_placeholder",
    razorpayKeySecret: env.RAZORPAY_KEY_SECRET || "rzp_secret_placeholder",
    // No placeholder fallback: an unset secret must never validate a webhook signature
    razorpayWebhookSecret: env.RAZORPAY_WEBHOOK_SECRET || "",
    currency: "INR",
    reservationHoldMinutes: 10,
  };
}

export function rupeesToPaise(rupees: number): number {
  return Math.round(rupees * 100);
}

export function paiseToRupees(paise: number): number {
  return paise / 100;
}
