import { generateQRHash } from "../../utils/crypto";
import { logger } from "../../utils/logger";
import { ConflictError, NotFoundError } from "../../errors/app-error";
import type { PrismaDb } from "./prisma-db";

export class BookingConfirmationRepository {
  constructor(private readonly db: PrismaDb) {}

  /**
   * Resolves reservation to full checkout atomically.
   */
  async confirmBooking(
    bookingId: string,
    transactionId: string,
    method: string,
    rzpDetails?: {
      razorpayOrderId?: string;
      razorpayPaymentId?: string;
      razorpaySignature?: string;
    },
    options?: {
      allowGracePeriod?: boolean;
      gracePeriodMinutes?: number;
    }
  ) {
    return this.db.$transaction(async (tx) => {
      const booking = await tx.booking.findUnique({
        where: { id: bookingId },
        include: {
          items: true,
          user: true,
          tickets: true,
        },
      });

      if (!booking) {
        throw new NotFoundError("Booking not found.");
      }

      if (booking.status === "CONFIRMED") {
        // Self-heal any ticket that was previously stuck in an unconfirmed status or missing qrToken
        const unconfirmedTickets = booking.tickets.filter((t) => t.status !== "CONFIRMED" || !t.qrToken);
        if (unconfirmedTickets.length > 0) {
          const userEmail = booking.user?.email || "attendee@happenins.com";
          for (const ticket of unconfirmedTickets) {
            const qrHash = ticket.qrToken || generateQRHash(ticket.id, userEmail);
            await tx.ticket.update({
              where: { id: ticket.id },
              data: {
                status: "CONFIRMED",
                qrToken: qrHash,
              },
            });
          }
        }
        return booking; // Already confirmed - idempotent
      }

      if (booking.status === "EXPIRED" || booking.status === "CANCELLED") {
        throw new ConflictError(`Cannot confirm payment for booking in '${booking.status}' status.`);
      }

      // Check expiry invariant: cannot confirm an expired reservation even if cleanup worker hasn't run yet
      const graceMs = options?.allowGracePeriod ? (options.gracePeriodMinutes ?? 15) * 60 * 1000 : 0;
      const effectiveExpiry = new Date(booking.reservedUntil.getTime() + graceMs);
      if (new Date() > effectiveExpiry) {
        // Mark as EXPIRED immediately
        await tx.booking.update({
          where: { id: bookingId },
          data: { status: "EXPIRED" },
        });
        throw new ConflictError("Reservation has expired. Payment confirmation rejected.");
      }

      // Convert RESERVED to CONFIRMED
      const updatedBooking = await tx.booking.update({
        where: { id: bookingId },
        data: {
          status: "CONFIRMED",
          razorpayOrderId: rzpDetails?.razorpayOrderId || booking.razorpayOrderId,
          razorpayPaymentId: rzpDetails?.razorpayPaymentId || transactionId,
        },
      });

      // Track capacity sale
      for (const item of booking.items) {
        await tx.ticketTier.update({
          where: { id: item.ticketTierId },
          data: {
            reserved: { decrement: item.quantity },
            sold: { increment: item.quantity },
          },
        });
      }

      // Convert held seats to SOLD
      await tx.eventSeat.updateMany({
        where: { bookingId },
        data: {
          status: "SOLD",
          heldUntil: null,
        },
      });

      // Update individual Tickets to CONFIRMED and issue QR credentials
      const userEmail = booking.user?.email || "attendee@happenins.com";
      let primaryQrHash = "";
      for (const ticket of booking.tickets) {
        const qrHash = generateQRHash(ticket.id, userEmail);
        if (!primaryQrHash) primaryQrHash = qrHash;
        await tx.ticket.update({
          where: { id: ticket.id },
          data: {
            status: "CONFIRMED",
            qrToken: qrHash,
          },
        });
      }

      if (!primaryQrHash) {
        primaryQrHash = generateQRHash(bookingId, userEmail);
      }

      // Upsert Attendance pass record
      await tx.attendance.upsert({
        where: { bookingId },
        create: {
          bookingId,
          qrHash: primaryQrHash,
        },
        update: {
          qrHash: primaryQrHash,
        },
      });

      // Record or update Payment entry idempotently
      await tx.payment.upsert({
        where: { transactionId },
        create: {
          bookingId,
          transactionId,
          razorpayOrderId: rzpDetails?.razorpayOrderId || booking.razorpayOrderId,
          razorpayPaymentId: rzpDetails?.razorpayPaymentId || transactionId,
          razorpaySignature: rzpDetails?.razorpaySignature,
          provider: rzpDetails?.razorpayPaymentId ? "RAZORPAY" : "LOCAL",
          amount: booking.totalAmount,
          currency: "INR",
          status: "CAPTURED",
          method,
          reconciledAt: new Date(),
        },
        update: {
          status: "CAPTURED",
          reconciledAt: new Date(),
          razorpayOrderId: rzpDetails?.razorpayOrderId || undefined,
          razorpayPaymentId: rzpDetails?.razorpayPaymentId || undefined,
          razorpaySignature: rzpDetails?.razorpaySignature || undefined,
        },
      });

      return updatedBooking;
    });
  }

  /**
   * Atomically and idempotently expires a specific booking and releases capacities & seats.
   * Uses conditional update (status === "RESERVED" AND reservedUntil < now) to prevent double-decrements.
   */
  async releaseExpiredBooking(bookingId: string): Promise<boolean> {
    return this.db.$transaction(async (tx) => {
      const updated = await tx.booking.updateMany({
        where: {
          id: bookingId,
          status: "RESERVED",
          reservedUntil: { lt: new Date() },
        },
        data: { status: "EXPIRED" },
      });

      // If count is 0, this booking was already confirmed, already expired, or not yet expired
      if (updated.count === 0) {
        return false;
      }

      const booking = await tx.booking.findUnique({
        where: { id: bookingId },
        include: { items: true },
      });

      if (!booking) return false;

      // Cancel associated tickets
      await tx.ticket.updateMany({
        where: { bookingId: booking.id },
        data: { status: "CANCELLED" },
      });

      // Release seats
      await tx.eventSeat.updateMany({
        where: { bookingId: booking.id, status: "HELD" },
        data: {
          status: "AVAILABLE",
          bookingId: null,
          heldUntil: null,
        },
      });

      // Release capacities
      for (const item of booking.items) {
        await tx.ticketTier.update({
          where: { id: item.ticketTierId },
          data: {
            reserved: { decrement: item.quantity },
          },
        });
      }

      return true;
    });
  }

  /**
   * Sweeps expired reservations and releases capacities & seats idempotently.
   * Safe across multiple concurrent workers.
   */
  async releaseExpiredReservations(): Promise<number> {
    const expiredReservations = await this.db.booking.findMany({
      where: {
        status: "RESERVED",
        reservedUntil: { lt: new Date() },
      },
      select: { id: true },
      take: 100, // Batch limit to prevent transaction bottlenecks
    });

    if (expiredReservations.length === 0) return 0;

    let releasedCount = 0;
    for (const b of expiredReservations) {
      try {
        const released = await this.releaseExpiredBooking(b.id);
        if (released) releasedCount++;
      } catch (err: unknown) {
        // Keep sweeping the rest, but a booking that cannot be released holds inventory: make it visible
        logger.error("Failed to release expired booking", { bookingId: b.id, message: err instanceof Error ? err.message : String(err) });
      }
    }

    return releasedCount;
  }
}
