import { Request, Response } from "express";
import { InstitutionService } from "../services/institution.service";
import { InstitutionOtpService } from "../services/institution-otp.service";
import { z } from "zod";
import { publicErrorMessage, respondWithError } from "../utils/http-error";

const createInstitutionSchema = z.object({
  name: z.string().min(2, "Institution name is required"),
  type: z.enum(["COLLEGE", "UNIVERSITY", "SCHOOL", "COMPANY", "ORGANIZATION", "OTHER"]).default("COLLEGE"),
  primaryDomain: z.string().min(3, "Primary domain is required"),
  logoUrl: z.string().optional(),
  additionalDomains: z.array(z.string()).optional(),
});

const sendOtpSchema = z.object({
  eventId: z.string().min(1, "Event ID is required"),
  collegeEmail: z.string().email("Please enter a valid college email address"),
});

const verifyOtpSchema = z.object({
  eventId: z.string().min(1, "Event ID is required"),
  collegeEmail: z.string().email("Please enter a valid college email address"),
  otp: z.string().min(6, "6-digit OTP is required").max(6, "6-digit OTP is required"),
});

export class InstitutionController {
  private service = new InstitutionService();
  private otpService = new InstitutionOtpService();

  getInstitutions = async (req: Request, res: Response) => {
    try {
      const search = req.query.search as string;
      const type = req.query.type as string;

      const list = await this.service.getInstitutions(search, type);
      res.status(200).json(list);
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 500);
    }
  };

  checkDomain = async (req: Request, res: Response) => {
    try {
      const domain = req.query.domain as string;
      if (!domain) {
        return res.status(400).json({ error: "Domain query parameter required" });
      }

      const inst = await this.service.getInstitutionByDomain(domain);
      if (!inst) {
        return res.status(200).json({
          matched: false,
          domain,
          institution: null,
        });
      }

      res.status(200).json({
        matched: true,
        domain,
        institution: inst,
      });
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 500);
    }
  };

  createInstitution = async (req: Request, res: Response) => {
    try {
      const body = createInstitutionSchema.parse(req.body);
      const created = await this.service.createInstitution(body);
      res.status(201).json(created);
    } catch (err: unknown) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ error: err.issues[0].message });
      } else {
        respondWithError(res, err, "Failed to create institution", 400);
      }
    }
  };

  sendOtp = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Please log in to verify your college email." });
      }

      const body = sendOtpSchema.parse(req.body);
      const result = await this.otpService.sendOtp(req.user.id, body.eventId, body.collegeEmail);
      res.status(200).json(result);
    } catch (err: unknown) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ error: err.issues[0].message });
      } else {
        respondWithError(res, err, "Failed to dispatch OTP.", 400);
      }
    }
  };

  verifyOtp = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Please log in to verify your college email." });
      }

      const body = verifyOtpSchema.parse(req.body);
      const result = await this.otpService.verifyOtp(
        req.user.id,
        body.eventId,
        body.collegeEmail,
        body.otp
      );
      res.status(200).json(result);
    } catch (err: unknown) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ error: err.issues[0].message });
      } else {
        respondWithError(res, err, "Failed to verify OTP.", 400);
      }
    }
  };

  getOtpStatus = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(200).json({ isVerified: false });
      }

      const eventId = req.query.eventId as string;
      if (!eventId) {
        return res.status(400).json({ error: "eventId query parameter is required." });
      }

      const result = await this.otpService.getVerificationStatus(req.user.id, eventId);
      res.status(200).json(result);
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 500);
    }
  };
}
