import jwt from "jsonwebtoken";
import crypto from "crypto";
import { getEnv } from "../config/env";
import { getSecurityConfig } from "../config/security";
import { UserSession } from "../../types";
import { authWorkerPool } from "./auth-worker-pool";

const getJwtSecret = (): string => {
  return getEnv().JWT_SECRET;
};

const getQrHmacSecret = (): string => {
  return getEnv().QR_HMAC_SECRET;
};

export async function hashPassword(password: string): Promise<string> {
  return authWorkerPool.hashPassword(password, getSecurityConfig().bcryptSaltRounds);
}

export async function comparePassword(password: string, hash: string): Promise<boolean> {
  try {
    return await authWorkerPool.comparePassword(password, hash);
  } catch (err: unknown) {
    return false;
  }
}

export function signAccessToken(session: UserSession, sessionId?: string): string {
  return jwt.sign(
    {
      id: session.id,
      email: session.email,
      fullName: session.fullName,
      avatarUrl: session.avatarUrl,
      role: session.role,
      sessionId: sessionId || undefined,
    },
    getJwtSecret(),
    {
      expiresIn: (getSecurityConfig().jwtExpiresIn || "7d") as any,
      issuer: "happenins",
      audience: "happenins-client",
    }
  );
}

export function verifyToken(token: string): any {
  try {
    const decoded: any = jwt.verify(token, getJwtSecret(), {
      issuer: "happenins",
      audience: ["happenins-client", "happenins-staff-scanner"],
    });
    // Audience must match the token shape: scanner tokens never act as user tokens and vice-versa
    const isStaff = decoded.role === "STAFF_SCANNER";
    if (isStaff !== (decoded.aud === "happenins-staff-scanner")) return null;
    return decoded;
  } catch (err: unknown) {
    return null;
  }
}

export function hashToken(rawToken: string): string {
  return crypto.createHash("sha256").update(rawToken).digest("hex");
}

export function generateSecureToken(bytes = 32): string {
  return crypto.randomBytes(bytes).toString("hex");
}

export function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString("base64url");
}

export function generateCodeChallenge(verifier: string): string {
  return crypto.createHash("sha256").update(verifier).digest("base64url");
}

export function safeCompareStrings(a: string, b: string): boolean {
  if (typeof a !== "string" || typeof b !== "string") return false;
  const bufA = Buffer.from(a, "utf-8");
  const bufB = Buffer.from(b, "utf-8");
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

export function generateQRHash(ticketId: string, email: string): string {
  const message = `${ticketId}:${email}`;
  const fullHash = crypto
    .createHmac("sha256", getQrHmacSecret())
    .update(message)
    .digest("hex");
  // 64-bit HMAC signature prefixed with ticket identifier for deterministic verification & security
  return `HPN-${ticketId}-${fullHash.substring(0, 16).toUpperCase()}`;
}

export function verifyQRHash(hash: string, ticketId: string, email: string): boolean {
  if (!hash || typeof hash !== "string") return false;
  const trimmed = hash.trim().toUpperCase();
  const message = `${ticketId}:${email}`;
  const fullHash = crypto
    .createHmac("sha256", getQrHmacSecret())
    .update(message)
    .digest("hex");

  // Primary 64-bit format: HPN-<ticketId>-<16-hex>
  const primaryLongHash = `HPN-${ticketId}-${fullHash.substring(0, 16)}`.toUpperCase();
  if (safeCompareStrings(trimmed, primaryLongHash)) {
    return true;
  }

  return false;
}

export function generateDynamicQRToken(ticketReference: string, customTimeWindow?: number): { token: string; timeWindow: number } {
  const windowMs = 30000; // 30 seconds
  const timeWindow = customTimeWindow || Math.floor(Date.now() / windowMs);
  const sig = crypto
    .createHmac("sha256", getQrHmacSecret())
    .update(`ROT:${ticketReference}:${timeWindow}`)
    .digest("hex"); // full 64-character SHA256 hex
  
  return {
    token: `ROT:${ticketReference}:${timeWindow}:${sig}`,
    timeWindow,
  };
}

export function parseAndVerifyDynamicQRToken(rawInput: string): { valid: boolean; qrHash: string; isDynamic: boolean; reason?: string } {
  if (!rawInput || typeof rawInput !== "string") {
    return { valid: false, qrHash: "", isDynamic: false, reason: "Empty or invalid QR code input." };
  }

  const input = rawInput.trim();
  if (input.startsWith("ROT:")) {
    const parts = input.split(":");
    if (parts.length !== 4) {
      return { valid: false, qrHash: "", isDynamic: true, reason: "Malformed dynamic QR code token." };
    }

    const [, ticketRef, timeWindowStr, signature] = parts;
    if (!ticketRef || !signature) {
      return { valid: false, qrHash: "", isDynamic: true, reason: "Malformed dynamic QR code token components." };
    }

    const timeWindow = parseInt(timeWindowStr, 10);
    if (isNaN(timeWindow)) {
      return { valid: false, qrHash: "", isDynamic: true, reason: "Invalid time window in QR token." };
    }

    const currentTimeWindow = Math.floor(Date.now() / 30000);
    // Allow a grace window of +-2 (60s) for clock drift
    if (Math.abs(currentTimeWindow - timeWindow) > 2) {
      return { valid: false, qrHash: "", isDynamic: true, reason: "Anti-screenshot security: Dynamic QR code expired! Please refresh your pass." };
    }

    const expectedSig = crypto
      .createHmac("sha256", getQrHmacSecret())
      .update(`ROT:${ticketRef}:${timeWindow}`)
      .digest("hex");

    if (!safeCompareStrings(signature.toLowerCase(), expectedSig.toLowerCase())) {
      return { valid: false, qrHash: "", isDynamic: true, reason: "Tampered or counterfeit dynamic QR code detected." };
    }

    return { valid: true, qrHash: ticketRef, isDynamic: true };
  }

  // Static Token Verification:
  // Legitimate Happenins ticket QR tokens must follow the cryptographic HPN- format.
  // Public identifiers (ticket numbers, invoices, database IDs) are explicitly rejected as QR credentials.
  const upper = input.toUpperCase();
  if (upper.startsWith("HPN-")) {
    const body = input.substring(4);
    // Must contain valid token characters and minimum length (at least 8 characters)
    if (body.length >= 8 && /^[A-Za-z0-9_-]+$/.test(body)) {
      return { valid: true, qrHash: input, isDynamic: false };
    }
  }

  return {
    valid: false,
    qrHash: "",
    isDynamic: false,
    reason: "Public identifiers (ticket numbers, invoices, booking IDs) or unrecognized tokens cannot be used as cryptographic QR verification passes.",
  };
}

export function generateStaffPin(): string {
  // Generate a cryptographically secure 6-digit numeric PIN (e.g. 100000 - 999999)
  const pinNum = crypto.randomInt(100000, 1000000);
  return pinNum.toString();
}

export function signStaffToken(payload: {
  staffScannerId: string;
  eventId: string;
  staffName: string;
  gateName: string;
  allowedTiers: string;
  allowedTierNames?: string[];
}, expiresInSeconds = 12 * 60 * 60): string {
  return jwt.sign(
    {
      id: payload.staffScannerId,
      staffScannerId: payload.staffScannerId,
      eventId: payload.eventId,
      staffName: payload.staffName,
      gateName: payload.gateName,
      allowedTiers: payload.allowedTiers,
      allowedTierNames: payload.allowedTierNames || [],
      role: "STAFF_SCANNER",
    },
    getJwtSecret(),
    {
      expiresIn: Math.max(60, Math.floor(expiresInSeconds)),
      issuer: "happenins",
      audience: "happenins-staff-scanner",
    }
  );
}

