import { getPrisma } from "../utils/db";
import { generateSecureToken, hashToken, signAccessToken } from "../utils/crypto";
import { UserSession, UserRole } from "../../types";
import { UnauthorizedError } from "../errors/app-error";
import { sessionRevocationService } from "./session-revocation.service";

export class SessionService {
  private prisma = getPrisma();

  async createSession(
    userId: string,
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ rawRefreshToken: string; accessToken: string; session: any; user: UserSession }> {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
    });

    if (!user) {
      throw new UnauthorizedError("User account not found.");
    }

    const rawRefreshToken = generateSecureToken(32);
    const refreshTokenHash = hashToken(rawRefreshToken);
    const familyId = "fam_" + generateSecureToken(16);
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

    const session = await this.prisma.session.create({
      data: {
        userId: user.id,
        refreshTokenHash,
        familyId,
        ipAddress: ipAddress || null,
        userAgent: userAgent || null,
        expiresAt,
      },
    });

    const userSession: UserSession = {
      id: user.id,
      email: user.email,
      fullName: user.fullName,
      avatarUrl: user.avatarUrl,
      role: user.role as UserRole,
    };

    const accessToken = signAccessToken(userSession, session.id);
    sessionRevocationService.clearUserRevocation(user.id);

    return { rawRefreshToken, accessToken, session, user: userSession };
  }

  async rotateSession(
    rawRefreshToken: string,
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ newRawRefreshToken: string; accessToken: string; user: UserSession }> {
    const refreshTokenHash = hashToken(rawRefreshToken);
    const existingSession = await this.prisma.session.findUnique({
      where: { refreshTokenHash },
      include: { user: true },
    });

    if (!existingSession) {
      throw new UnauthorizedError("Invalid or expired session token.");
    }

    // Reuse detection: If token was already revoked, revoke the ENTIRE token family
    if (existingSession.revokedAt) {
      // 30-second grace window for concurrent requests from the same client
      const gracePeriodMs = 30000;
      if (
        existingSession.revokedReason === "ROTATED" &&
        existingSession.revokedAt &&
        Date.now() - existingSession.revokedAt.getTime() < gracePeriodMs
      ) {
        const latestSession = await this.prisma.session.findFirst({
          where: { familyId: existingSession.familyId, revokedAt: null },
          orderBy: { createdAt: "desc" },
          include: { user: true },
        });

        if (latestSession && latestSession.expiresAt > new Date()) {
          const userSession: UserSession = {
            id: latestSession.user.id,
            email: latestSession.user.email,
            fullName: latestSession.user.fullName,
            avatarUrl: latestSession.user.avatarUrl,
            role: latestSession.user.role as UserRole,
          };
          const accessToken = signAccessToken(userSession, latestSession.id);
          return {
            newRawRefreshToken: rawRefreshToken,
            accessToken,
            user: userSession,
          };
        }
      }

      await this.prisma.session.updateMany({
        where: { familyId: existingSession.familyId, revokedAt: null },
        data: {
          revokedAt: new Date(),
          revokedReason: "TOKEN_REUSE_DETECTED",
        },
      });
      throw new UnauthorizedError("Security Alert: Session revoked due to token reuse detection.");
    }

    if (existingSession.expiresAt < new Date()) {
      await this.prisma.session.update({
        where: { id: existingSession.id },
        data: { revokedAt: new Date(), revokedReason: "EXPIRED" },
      });
      throw new UnauthorizedError("Session expired. Please log in again.");
    }

    // Revoke old token as ROTATED
    await this.prisma.session.update({
      where: { id: existingSession.id },
      data: {
        revokedAt: new Date(),
        revokedReason: "ROTATED",
        lastUsedAt: new Date(),
      },
    });

    // Create rotated session
    const newRawRefreshToken = generateSecureToken(32);
    const newRefreshTokenHash = hashToken(newRawRefreshToken);
    const newExpiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

    const newSession = await this.prisma.session.create({
      data: {
        userId: existingSession.userId,
        refreshTokenHash: newRefreshTokenHash,
        familyId: existingSession.familyId,
        ipAddress: ipAddress || existingSession.ipAddress,
        userAgent: userAgent || existingSession.userAgent,
        expiresAt: newExpiresAt,
      },
    });

    const userSession: UserSession = {
      id: existingSession.user.id,
      email: existingSession.user.email,
      fullName: existingSession.user.fullName,
      avatarUrl: existingSession.user.avatarUrl,
      role: existingSession.user.role as UserRole,
    };

    const accessToken = signAccessToken(userSession, newSession.id);
    sessionRevocationService.clearUserRevocation(existingSession.userId);

    return {
      newRawRefreshToken,
      accessToken,
      user: userSession,
    };
  }

  async revokeSession(rawRefreshToken: string, reason = "LOGOUT"): Promise<void> {
    const refreshTokenHash = hashToken(rawRefreshToken);
    const existing = await this.prisma.session.findUnique({
      where: { refreshTokenHash },
      select: { id: true, userId: true },
    });

    if (existing) {
      // Instantly register in Redis / in-memory revocation cache (0.05ms)
      await sessionRevocationService.revokeSession(existing.id, existing.userId);
    }

    await this.prisma.session.updateMany({
      where: { refreshTokenHash, revokedAt: null },
      data: {
        revokedAt: new Date(),
        revokedReason: reason,
      },
    });
  }

  async revokeAllUserSessions(userId: string, reason = "PASSWORD_RESET"): Promise<void> {
    // Instantly register in Redis / in-memory revocation cache
    await sessionRevocationService.revokeAllUserSessions(userId);

    await this.prisma.session.updateMany({
      where: { userId, revokedAt: null },
      data: {
        revokedAt: new Date(),
        revokedReason: reason,
      },
    });
  }
}
