import type { Response } from "express";
import { ZodError } from "zod";
import { AppError } from "../errors/app-error";
import { logger } from "./logger";
export { errorMessage } from "./error-message";

const INTERNAL_MESSAGE_PATTERN = /prisma|invocation|ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|socket hang up|razorpay|smtp|redis|relation ".*" does not exist|\bat .+\(.+:\d+:\d+\)/i;

/**
 * Message safe to return to API clients. Domain errors (AppError or plain Errors thrown by services
 * with user-facing text) pass through; errors originating in Prisma, Razorpay, SMTP, Redis or the
 * network stack are logged and replaced with the generic fallback.
 */
export function publicErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof AppError) return error.message || fallback;
  const err = (error ?? {}) as { message?: unknown; code?: unknown; name?: unknown; error?: unknown; errno?: unknown; syscall?: unknown };

  const message: string = typeof err.message === "string" ? err.message : "";
  const looksInternal =
    !message ||
    message.length > 300 ||
    (typeof err.code === "string" && /^P\d{4}$/.test(err.code)) ||
    /prisma|razorpay/i.test(typeof err.name === "string" ? err.name : "") ||
    (err.error && typeof err.error === "object") || // Razorpay SDK error shape
    err.errno !== undefined ||
    err.syscall !== undefined ||
    INTERNAL_MESSAGE_PATTERN.test(message);

  if (looksInternal) {
    logger.error("Suppressed internal error from API response", { message: message.slice(0, 500), name: err.name as string | undefined, code: err.code as string | undefined });
    return fallback;
  }
  return message;
}

/**
 * Single place that turns a thrown error into an HTTP response.
 * Typed AppErrors keep their own status (404, 403, 409, 429...); anything else uses the route's
 * default status (400 for input problems, 500 for server-side operations) and goes through publicErrorMessage.
 */
export function respondWithError(res: Response, err: unknown, fallback: string, defaultStatus = 400): void {
  if (err instanceof ZodError) {
    res.status(400).json({ error: err.issues[0]?.message || "Invalid request" });
    return;
  }
  const status = err instanceof AppError ? err.statusCode : defaultStatus;
  res.status(status).json({ error: publicErrorMessage(err, fallback) });
}
