import nodemailer from "nodemailer";
import { EmailJobData } from "../jobs/types";
import { jobQueue } from "../jobs/queue";
import { logger } from "./logger";
import { sendVentureMail } from "./multiSmtpRouter";
import { formatDateIST } from "../../lib/formatters";

export interface SimulatedEmail {
  id: string;
  to: string;
  subject: string;
  body: string;
  sentAt: string;
}

export const memoryEmails: SimulatedEmail[] = [];

/**
 * Access in-memory sandbox emails for development, preview, and test drawers.
 */
export const getEmailsForUser = (emailAddress: string) => {
  if (!emailAddress) return [];
  return memoryEmails.filter(
    (e) => e.to.toLowerCase().trim() === emailAddress.toLowerCase().trim()
  );
};

export const clearMemoryEmails = () => {
  memoryEmails.length = 0;
};

import { getEmailConfig } from "../config/email";
import { errorMessage } from "./error-message";

// Lazy initialization of SMTP transport
let smtpTransport: any = null;

export const checkSMTPConfigured = (): boolean => {
  const config = getEmailConfig();
  return config.isConfigured;
};

const getSMTPTransport = () => {
  const config = getEmailConfig();
  if (!config.isConfigured) return null;

  if (!smtpTransport) {
    try {
      smtpTransport = nodemailer.createTransport({
        host: config.host,
        port: config.port,
        secure: config.port === 465,
        auth: {
          user: config.user,
          pass: config.pass,
        },
        connectionTimeout: 15000,
        greetingTimeout: 15000,
        socketTimeout: 20000,
      });
    } catch (err: unknown) {
      logger.error("[SMTP CONFIG ERROR] Failed to initialize mail transport:", { error: errorMessage(err) });
    }
  }
  return smtpTransport;
};

const escapeHtml = (v: string) =>
  v.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

// Escapes user-influenced text, then turns plain https URLs into links
const toSafeHtmlLine = (line: string) =>
  escapeHtml(line).replace(/https?:\/\/[^\s<]+/g, (url) => `<a href="${url}" style="color: #7c3aed;">${url}</a>`);

// Anti-spam compliant HTML template for transactional emails
export const buildDeliverableHtml = (subject: string, bodyText: string, customHtml?: string) => {
  if (customHtml) return customHtml;

  const formattedLines = bodyText
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map((line) => `<p style="margin: 0 0 12px 0; font-size: 14px; line-height: 1.6; color: #334155;">${toSafeHtmlLine(line)}</p>`)
    .join("");

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(subject)}</title>
</head>
<body style="margin: 0; padding: 0; background-color: #f8fafc; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
  <table role="presentation" width="100%" border="0" cellspacing="0" cellpadding="0" style="background-color: #f8fafc; padding: 32px 16px;">
    <tr>
      <td align="center">
        <table role="presentation" width="100%" border="0" cellspacing="0" cellpadding="0" style="max-width: 580px; background-color: #ffffff; border-radius: 16px; border: 1px solid #e2e8f0; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);">
          <tr>
            <td style="background-color: #09091b; padding: 28px 32px; text-align: left;">
              <span style="font-size: 20px; font-weight: 800; color: #ffffff; letter-spacing: -0.5px;">
                Happenins <span style="color: #a855f7; font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 1px;">• Verified Ticket Registry</span>
              </span>
            </td>
          </tr>
          <tr>
            <td style="padding: 32px; text-align: left;">
              <h2 style="margin: 0 0 16px 0; font-size: 18px; font-weight: 700; color: #0f172a; letter-spacing: -0.3px;">${escapeHtml(subject)}</h2>
              ${formattedLines}
            </td>
          </tr>
          <tr>
            <td style="background-color: #f1f5f9; padding: 20px 32px; border-top: 1px solid #e2e8f0; font-size: 11px; color: #64748b; line-height: 1.5; text-align: left;">
              <p style="margin: 0 0 6px 0; font-weight: 600; color: #475569;">Authentic Transactional Communication</p>
              <p style="margin: 0;">This email was sent from an automated system to confirm your account activity or ticket status.</p>
              <p style="margin: 8px 0 0 0; color: #94a3b8;">© ${new Date().getFullYear()} Happenins Marketplace. All rights reserved.</p>
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
};

/**
 * Worker-Executed Delivery Function:
 * Delivers email via Multi-SMTP router with automatic fallback accounts (AUTH -> STAGE_1 -> STAGE_3).
 * In test mode, records safely in memory sandbox without triggering network requests.
 */
export async function deliverTransactionalEmail(data: EmailJobData): Promise<void> {
  const isTest = process.env.NODE_ENV === "test" || process.env.VITEST === "true";
  const isProd = process.env.NODE_ENV === "production";

  // Deduplication / Idempotency check: prevent duplicate delivery for the same logical message
  if (data.messageId && memoryEmails.some((e) => e.id === data.messageId)) {
    logger.info("Skipping duplicate email delivery attempt:", { messageId: data.messageId, to: data.to });
    return;
  }

  // Always record transactional emails into memory buffer for in-app simulated inbox & audit
  const istSentAt = formatDateIST(new Date(), {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  });

  memoryEmails.unshift({
    id: data.messageId,
    to: data.to,
    subject: isProd ? "[redacted]" : data.subject,
    body: isProd ? "" : data.body,
    sentAt: istSentAt,
  });

  // Cap memory email history
  if (memoryEmails.length > 150) {
    memoryEmails.length = 150;
  }

  // Unit tests skip network delivery
  if (isTest) {
    return;
  }

  const finalHtml = buildDeliverableHtml(data.subject, data.body, data.html);

  try {
    const res = await sendVentureMail({
      stage: "AUTH",
      to: data.to,
      subject: data.subject,
      html: finalHtml,
      text: data.body,
    });

    if (res.success) {
      logger.info(`[TRANSACTIONAL EMAIL] Successfully delivered to ${data.to} via ${res.sentVia} [MsgId: ${data.messageId}]`);
    } else {
      logger.error(`[TRANSACTIONAL EMAIL ERROR] Delivery failed for ${data.to}: ${res.error}`);
      throw new Error(`SMTP_DELIVERY_FAILED: ${res.error}`);
    }
  } catch (err: unknown) {
    const sanitizedError = (errorMessage(err) || "").replace(/pass(?:word)?\s*[:=]\s*[^\s]+/gi, "password=[REDACTED]");
    logger.error(`SMTP delivery failed for ${data.to}:`, { messageId: data.messageId, error: sanitizedError });
    throw new Error(`SMTP_DELIVERY_FAILED: ${sanitizedError}`);
  }
}

/**
 * Enqueue / direct dispatch transactional email.
 * Immediately awaits delivery to ensure completion on serverless runtimes (e.g. Vercel)
 * where unawaited background tasks would freeze upon request completion.
 */
export async function enqueueTransactionalEmail(
  to: string,
  subject: string,
  body: string,
  htmlContent?: string,
  customMessageId?: string
): Promise<string> {
  const messageId = customMessageId || `eml_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
  const emailData: EmailJobData = {
    to,
    subject,
    body,
    html: htmlContent,
    messageId,
  };

  await deliverTransactionalEmail(emailData);

  return messageId;
}

/**
 * Backward-compatible helper for services.
 * Dispatches transactional email immediately and returns a thenable record.
 */
export const sendSimulatedEmail = (to: string, subject: string, body: string, htmlContent?: string) => {
  const id = "eml_" + Math.random().toString(36).substring(2, 11);
  const emailData: EmailJobData = {
    to,
    subject,
    body,
    html: htmlContent,
    messageId: id,
  };

  const deliveryPromise = deliverTransactionalEmail(emailData).catch((err) => {
    logger.warn("Failed to deliver transactional email:", { error: err.message, messageId: id });
  });

  const record = {
    id,
    to,
    subject,
    body,
    sentAt: new Date().toISOString(),
  };

  return Object.assign(deliveryPromise.then(() => record), record);
};
