import { Request, Response, NextFunction } from "express";
import { verifyToken } from "../utils/crypto";
import { UserSession, UserRole } from "../../types";
import { UnauthorizedError, ForbiddenError } from "../errors/app-error";
import { getPrisma } from "../utils/db";
import { sessionRevocationService } from "../services/session-revocation.service";

declare global {
  namespace Express {
    interface Request {
      user?: UserSession;
      sessionId?: string;
      id?: string;
      traceId?: string;
      spanId?: string;
      staffScanner?: {
        id: string;
        eventId: string;
        staffName: string;
        gateName: string;
        allowedTiers: string;
        allowedTierNames: string[];
      };
    }
  }
}

export async function authMiddleware(req: Request, res: Response, next: NextFunction) {
  try {
    const authHeader = req.headers.authorization;
    let token: string | undefined;

    if (authHeader && authHeader.startsWith("Bearer ")) {
      token = authHeader.split(" ")[1];
    } else if (req.cookies?.token) {
      token = req.cookies.token;
    }

    if (!token) {
      return next();
    }

    let decoded = token ? verifyToken(token) : null;

    // If access token is expired or missing but a valid refresh token exists in cookies, silently recover session
    if (!decoded && req.cookies?.refreshToken) {
      try {
        const { SessionService } = await import("../services/session.service");
        const sessionService = new SessionService();
        const rotated = await sessionService.rotateSession(req.cookies.refreshToken, req.ip, req.get("User-Agent"));
        if (rotated) {
          const { getSecurityConfig } = await import("../config/security");
          const { cookieSameSite: sameSite, cookieSecure: secure } = getSecurityConfig();
          res.cookie("refreshToken", rotated.newRawRefreshToken, {
            httpOnly: true,
            secure,
            sameSite,
            path: "/",
            maxAge: 7 * 24 * 60 * 60 * 1000,
          });
          res.cookie("token", rotated.accessToken, {
            httpOnly: true,
            secure,
            sameSite,
            path: "/",
            maxAge: 7 * 24 * 60 * 60 * 1000,
          });
          token = rotated.accessToken;
          decoded = verifyToken(token);
        }
      } catch {
        // Refresh token invalid or expired, continue without user
      }
    }

    if (!decoded) {
      return next();
    }

    // Step 2: Check if it is a Staff Scanner session
    if (decoded.role === "STAFF_SCANNER" && decoded.staffScannerId && decoded.eventId) {
      let staff = await sessionRevocationService.getStaffScannerCache(decoded.staffScannerId);

      if (!staff) {
        staff = await getPrisma().staffScanner.findUnique({
          where: { id: decoded.staffScannerId },
          select: { id: true, pin: true, isActive: true, expiresAt: true, gateName: true, staffName: true, eventId: true, allowedTiers: true },
        });

        if (staff) {
          await sessionRevocationService.setStaffScannerCache(decoded.staffScannerId, staff, 60);
        }
      }

      if (staff && staff.isActive && (!staff.expiresAt || new Date(staff.expiresAt) > new Date())) {
        let allowedTierNames: string[] = [];
        if (staff.allowedTiers && staff.allowedTiers !== "ALL") {
          try {
            allowedTierNames = JSON.parse(staff.allowedTiers);
          } catch {
            allowedTierNames = staff.allowedTiers.split(",").map((s: string) => s.trim());
          }
        }

        req.staffScanner = {
          id: staff.id,
          eventId: staff.eventId,
          staffName: staff.staffName,
          gateName: staff.gateName,
          allowedTiers: staff.allowedTiers,
          allowedTierNames,
        };

        req.user = {
          id: `staff_${staff.id}`,
          email: `volunteer_${staff.id.substring(0, 8)}@gate.internal`,
          fullName: `${staff.staffName} (${staff.gateName})`,
          avatarUrl: null,
          role: "USER" as UserRole,
        };
        return next();
      }
    }

    // Step 3: Fast-Path Stateless User Session Validation
    if (decoded.id && decoded.email && decoded.role) {
      if (decoded.sessionId) {
        // Fast-path: Check Redis / In-Memory revocation set in ~0.05ms (ZERO SQL queries)
        const isRevoked = await sessionRevocationService.isSessionRevoked(decoded.sessionId, decoded.id, decoded.iat);
        if (isRevoked) {
          req.user = undefined;
          req.sessionId = undefined;
          return next();
        }

        req.user = {
          id: decoded.id,
          email: decoded.email,
          fullName: decoded.fullName || decoded.email.split("@")[0],
          avatarUrl: decoded.avatarUrl || null,
          role: decoded.role as UserRole,
        };
        req.sessionId = decoded.sessionId;
      }
      // Tokens without a sessionId cannot be revoked and are no longer accepted
    }

    next();
  } catch (err: unknown) {
    // If auth decoding fails, allow request to proceed without req.user
    next();
  }
}

export function requireAuth(req: Request, res: Response, next: NextFunction) {
  if (!req.user) {
    throw new UnauthorizedError("Authentication required to perform this action.");
  }
  next();
}

export function restrictTo(...roles: UserRole[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.user) {
      throw new UnauthorizedError("Authentication required.");
    }
    if (!roles.includes(req.user.role)) {
      throw new ForbiddenError("Forbidden: Insufficient privileges for this endpoint.");
    }
    next();
  };
}

export const requireAdmin = restrictTo("ADMIN");
export const requireOrganizerOrAdmin = restrictTo("ORGANIZER", "ADMIN");

export const VENTURE_MASTER_ADMIN_EMAIL = "pacific2306@gmail.com";

export function requireVentureMasterAdmin(req: Request, res: Response, next: NextFunction) {
  if (!req.user) {
    return res.status(401).json({ error: { code: "UNAUTHORIZED", message: "Authentication required to access Venture Vault." } });
  }

  const email = (req.user.email || "").trim().toLowerCase();
  if (email !== VENTURE_MASTER_ADMIN_EMAIL.toLowerCase() && req.user.role !== "ADMIN") {
    return res.status(403).json({ error: { code: "FORBIDDEN", message: "Access restricted to Venture Vault Master Admin." } });
  }

  next();
}
