import { formatDateIST, formatRupees } from "../../lib/formatters";

import { logger } from "../utils/logger";
export interface WhatsAppMessagePayload {
  toPhoneNumber: string;
  senderNumber: string;
  message: string;
  directUrl: string;
  type: "TICKET_CONFIRMATION" | "BOOKING_CANCELLATION" | "WALLET_REFUND";
  metadata?: Record<string, any>;
  timestamp: string;
}

export class WhatsAppService {
  // Configured Business Sender WhatsApp Contact Number
  public static readonly SENDER_NUMBER = "8767164611";
  public static readonly SENDER_NUMBER_FORMATTED = "+91 8767164611";
  public static readonly SENDER_NUMBER_INTERNATIONAL = "918767164611";

  /**
   * Generates a richly formatted WhatsApp ticket confirmation message.
   */
  public static formatTicketConfirmation(booking: any, user?: any, customAppUrl?: string): string {
    const appUrl = customAppUrl || process.env.APP_URL || "https://happenins.com";
    const userName = user?.fullName || booking.user?.fullName || "Valued Guest";
    const eventTitle = booking.event?.title || booking.eventTitle || "Special Event";
    const venue = booking.event?.venue || booking.eventVenue || "Venue Specified on Pass";
    const city = booking.event?.city ? `, ${booking.event.city}` : "";
    const invoiceNumber = booking.invoiceNumber || "INV-0000";

    // Format IST date and time
    let dateStr = "Date on Pass";
    if (booking.event?.startsAt || booking.eventStartsAt) {
      const rawDate = booking.event?.startsAt || booking.eventStartsAt;
      dateStr = formatDateIST(rawDate, {
        weekday: "short",
        month: "short",
        day: "numeric",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
        hour12: true,
      });
    }

    // Format items / tiers / seats
    const itemsList = (booking.items || []).map((item: any) => {
      const name = item.tierName || item.ticketTier?.name || "Standard";
      const qty = item.quantity || 1;
      const seatStr = item.seatNumbers ? ` (Seats: ${item.seatNumbers})` : "";
      return `  • ${name} × ${qty}${seatStr}`;
    }).join("\n") || "  • 1 × Standard Pass";

    const totalPaid = formatRupees(booking.totalAmount);
    const walletDeducted = booking.walletAmountApplied && booking.walletAmountApplied > 0
      ? `\n💰 *Wallet Applied:* ${formatRupees(booking.walletAmountApplied)}`
      : "";
    const discountStr = booking.discountAmount && booking.discountAmount > 0
      ? `\n🏷️ *Coupon Savings:* ${formatRupees(booking.discountAmount)}`
      : "";

    const passUrl = `${appUrl}/tickets?bookingId=${booking.id || ""}`;

    return (
      `🎟️ *HAPPENINS DIGITAL TICKET PASS* 🎟️\n` +
      `━━━━━━━━━━━━━━━━━━━━\n` +
      `Hello *${userName}*! 👋\n` +
      `Your booking for *${eventTitle}* is *CONFIRMED & VERIFIED* ✅\n\n` +
      `📋 *BOOKING SUMMARY:*\n` +
      `• *Invoice:* \`${invoiceNumber}\`\n` +
      `• *Event:* ${eventTitle}\n` +
      `• *Date & Time:* 🗓️ ${dateStr}\n` +
      `• *Location:* 📍 ${venue}${city}\n\n` +
      `🎫 *TICKETS & SEATS:*\n` +
      `${itemsList}\n\n` +
      `💳 *PAYMENT SUMMARY:*\n` +
      `• *Total Paid:* ${totalPaid}${walletDeducted}${discountStr}\n` +
      `• *Status:* Confirmed & Secured 🔒\n\n` +
      `━━━━━━━━━━━━━━━━━━━━\n` +
      `📲 *ACCESS YOUR LIVE DYNAMIC QR PASS:*\n` +
      `Show this rotating QR code at the venue gate for instant check-in:\n` +
      `👉 ${passUrl}\n\n` +
      `💬 *Need Assistance or Updates?*\n` +
      `Reach out to official Happenins WhatsApp support at *+91 ${this.SENDER_NUMBER}*.\n\n` +
      `_Thank you for choosing Happenins. Enjoy the experience!_ ✨`
    );
  }

  /**
   * Generates a cancellation & Happenins Wallet refund WhatsApp notification.
   */
  public static formatCancellationNotification(
    booking: any,
    refundAmount: number,
    cancellationFee: number,
    walletBalanceAfter: number,
    customAppUrl?: string
  ): string {
    const appUrl = customAppUrl || process.env.APP_URL || "https://happenins.com";
    const userName = booking.user?.fullName || "Valued Guest";
    const eventTitle = booking.event?.title || booking.eventTitle || "Event";
    const invoiceNumber = booking.invoiceNumber || "INV-0000";

    return (
      `⚠️ *HAPPENINS TICKET CANCELLATION & WALLET REFUND* ⚠️\n` +
      `━━━━━━━━━━━━━━━━━━━━\n` +
      `Hello *${userName}*,\n` +
      `Your booking \`${invoiceNumber}\` for *${eventTitle}* has been successfully cancelled.\n\n` +
      `💰 *CANCELLATION & REFUND BREAKDOWN:*\n` +
      `• *Original Booking Total:* ${formatRupees(booking.totalAmount)}\n` +
      `• *Cancellation Charges Deducted:* ${formatRupees(cancellationFee)}\n` +
      `• *Net Refund Credited:* *${formatRupees(refundAmount)}* 🪙\n\n` +
      `👛 *HAPPENINS WALLET UPDATE:*\n` +
      `The refund has been credited directly to your *Happenins Wallet*.\n` +
      `• *New Wallet Balance:* *${formatRupees(walletBalanceAfter)}*\n\n` +
      `💡 *How to use:* Your Happenins Wallet balance will automatically be available to deduct on your next ticket booking during checkout!\n\n` +
      `👉 Check your wallet & transaction ledger:\n` +
      `${appUrl}/settings\n\n` +
      `💬 Official WhatsApp Support: *+91 ${this.SENDER_NUMBER}*\n` +
      `_Team Happenins_`
    );
  }

  /**
   * Generates a direct WhatsApp web / app link with prefilled message.
   */
  public static getDirectWhatsAppLink(phoneNumber?: string, message?: string): string {
    const phone = phoneNumber
      ? phoneNumber.replace(/[^0-9]/g, "")
      : this.SENDER_NUMBER_INTERNATIONAL;
    
    const encodedMessage = encodeURIComponent(message || "Hello Happenins Support, I need assistance with my ticket.");
    return `https://wa.me/${phone}?text=${encodedMessage}`;
  }

  /**
   * Dispatches or simulates WhatsApp message dispatch.
   */
  public static async dispatchWhatsAppNotification(
    targetPhone: string,
    message: string,
    type: "TICKET_CONFIRMATION" | "BOOKING_CANCELLATION" | "WALLET_REFUND",
    metadata?: Record<string, any>
  ): Promise<WhatsAppMessagePayload> {
    const cleanedPhone = targetPhone ? targetPhone.replace(/[^0-9]/g, "") : this.SENDER_NUMBER_INTERNATIONAL;
    const directUrl = this.getDirectWhatsAppLink(cleanedPhone, message);

    const payload: WhatsAppMessagePayload = {
      toPhoneNumber: cleanedPhone,
      senderNumber: this.SENDER_NUMBER_INTERNATIONAL,
      message,
      directUrl,
      type,
      metadata,
      timestamp: new Date().toISOString(),
    };

    // Phone numbers and message bodies are PII: log only that a dispatch happened and its size
    logger.info("WhatsApp message dispatched (simulated)", { toLast4: cleanedPhone.slice(-4), length: message.length });

    return payload;
  }
}
