import { getEnv } from "./env";

export interface EmailConfig {
  host: string;
  port: number;
  user: string;
  pass: string;
  from: string;
  isConfigured: boolean;
}

export function getEmailConfig(): EmailConfig {
  const user = (process.env.SMTP_USER || "").trim();
  const host = (process.env.SMTP_HOST || (user.toLowerCase().includes("@gmail.com") ? "smtp.gmail.com" : "")).trim();
  const port = Number(process.env.SMTP_PORT || 587);
  // Strip whitespace from Gmail 16-character App Passwords if provided
  const rawPass = (process.env.SMTP_PASS || (user ? process.env.SMTP_SECRET : "") || "").trim();
  const pass = rawPass.replace(/\s+/g, "").trim();
  const rawFrom = (process.env.SMTP_FROM || user || "").trim();

  const fromAddress = rawFrom
    ? (rawFrom.includes("<") ? rawFrom : `"Happenins Events" <${rawFrom}>`)
    : "";

  const isConfigured = !!(host && user && pass);

  return {
    host,
    port,
    user,
    pass,
    from: fromAddress,
    isConfigured,
  };
}
