import { InstitutionRepository } from "../repositories/institution.repository";
import { InstitutionDTO, EventAccessPolicyDTO, EventEligibilityDTO } from "../../types";
import { isDomainAllowed, extractEmailDomain } from "../utils/domain-policy";

export class InstitutionService {
  private repo = new InstitutionRepository();

  private mapToDTO(inst: any): InstitutionDTO {
    return {
      id: inst.id,
      name: inst.name,
      slug: inst.slug,
      type: inst.type as any,
      logoUrl: inst.logoUrl,
      primaryDomain: inst.primaryDomain,
      isVerified: inst.isVerified,
      domains: inst.domains?.map((d: any) => ({
        id: d.id,
        institutionId: d.institutionId,
        domain: d.domain,
        isVerified: d.isVerified,
        createdAt: d.createdAt.toISOString(),
      })) || [],
      createdAt: inst.createdAt.toISOString(),
      updatedAt: inst.updatedAt.toISOString(),
    };
  }

  async getInstitutions(search?: string, type?: string): Promise<InstitutionDTO[]> {
    const list = await this.repo.findMany(search, type);
    return list.map((i) => this.mapToDTO(i));
  }

  async getInstitutionByDomain(domain: string): Promise<InstitutionDTO | null> {
    const inst = await this.repo.findInstitutionByDomain(domain);
    return inst ? this.mapToDTO(inst) : null;
  }

  async createInstitution(data: {
    name: string;
    type?: string;
    primaryDomain: string;
    logoUrl?: string;
    additionalDomains?: string[];
  }): Promise<InstitutionDTO> {
    const primary = data.primaryDomain.trim().toLowerCase();
    
    // Auto-generate safe slug
    let baseSlug = data.name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)+/g, "");
    if (!baseSlug) baseSlug = "institution";

    let slug = baseSlug;
    let idx = 1;
    while (await this.repo.findBySlug(slug)) {
      slug = `${baseSlug}-${idx}`;
      idx++;
    }

    const created = await this.repo.createInstitution({
      name: data.name,
      slug,
      type: data.type || "COLLEGE",
      logoUrl: data.logoUrl,
      primaryDomain: primary,
      additionalDomains: data.additionalDomains,
    });

    return this.mapToDTO(created!);
  }

  async seedDefaults(): Promise<void> {
    await this.repo.seedDefaultInstitutions();
  }

  /**
   * Evaluates if a user with a given email address satisfies an event's access policy.
   * Authoritative backend validation.
   */
  async evaluateEligibility(
    userEmail: string | null | undefined,
    accessPolicy?: EventAccessPolicyDTO | null
  ): Promise<EventEligibilityDTO> {
    // If no policy exists or policy is PUBLIC
    if (!accessPolicy || accessPolicy.policyType === "PUBLIC") {
      return {
        eligible: true,
        userEmail: userEmail || null,
        userDomain: userEmail ? userEmail.split("@")[1]?.toLowerCase() || null : null,
        policyType: "PUBLIC",
        allowedDomains: [],
        requireVerifiedEmail: false,
        reason: null,
      };
    }

    if (!userEmail) {
      return {
        eligible: false,
        userEmail: null,
        userDomain: null,
        policyType: accessPolicy.policyType as any,
        allowedDomains: accessPolicy.allowedDomains || [],
        requireVerifiedEmail: accessPolicy.requireVerifiedEmail ?? true,
        reason: "Authentication required to verify institution email eligibility.",
      };
    }

    const userDomain = userEmail.split("@")[1]?.toLowerCase().trim();
    if (!userDomain) {
      return {
        eligible: false,
        userEmail,
        userDomain: null,
        policyType: accessPolicy.policyType as any,
        allowedDomains: accessPolicy.allowedDomains || [],
        requireVerifiedEmail: accessPolicy.requireVerifiedEmail ?? true,
        reason: "Invalid email format.",
      };
    }

    const allowed = (accessPolicy.allowedDomains || []).map((d) => d.toLowerCase().trim());

    // Check domain match with strict prohibition of inverse matching
    const isDomainMatched = isDomainAllowed(userEmail, allowed);

    // Lookup matched institution info
    const matchedInst = await this.getInstitutionByDomain(userDomain);

    if (isDomainMatched) {
      return {
        eligible: true,
        userEmail,
        userDomain,
        policyType: accessPolicy.policyType as any,
        allowedDomains: accessPolicy.allowedDomains || [],
        requireVerifiedEmail: accessPolicy.requireVerifiedEmail ?? true,
        matchedInstitution: matchedInst
          ? {
              id: matchedInst.id,
              name: matchedInst.name,
              logoUrl: matchedInst.logoUrl,
              primaryDomain: matchedInst.primaryDomain,
            }
          : null,
        reason: null,
      };
    }

    // Ineligible domain reason
    const allowedListStr = allowed.map((d) => `@${d}`).join(", ");
    const customMsg = accessPolicy.customRestrictionMessage;
    const reasonMessage = customMsg
      ? customMsg
      : `Restricted Access: This event is exclusively reserved for members with verified emails ending in: ${allowedListStr}. Your email address (${userEmail}) is not eligible.`;

    return {
      eligible: false,
      userEmail,
      userDomain,
      policyType: accessPolicy.policyType as any,
      allowedDomains: accessPolicy.allowedDomains || [],
      requireVerifiedEmail: accessPolicy.requireVerifiedEmail ?? true,
      matchedInstitution: matchedInst
        ? {
            id: matchedInst.id,
            name: matchedInst.name,
            logoUrl: matchedInst.logoUrl,
            primaryDomain: matchedInst.primaryDomain,
          }
        : null,
      reason: reasonMessage,
    };
  }
}
