import { AsyncLocalStorage } from "async_hooks";

export interface RequestContext {
  requestId: string;
  traceId?: string;
  spanId?: string;
  userId?: string;
  userRole?: string;
  ipAddress?: string;
  userAgent?: string;
  path?: string;
  method?: string;
  startTime?: number;
}

const asyncLocalStorage = new AsyncLocalStorage<RequestContext>();

/**
 * Runs a function within an AsyncLocalStorage request context.
 */
export function runWithContext<T>(context: RequestContext, fn: () => T): T {
  return asyncLocalStorage.run(context, fn);
}

/**
 * Retrieves the current request context if available.
 */
export function getContext(): RequestContext | undefined {
  return asyncLocalStorage.getStore();
}

/**
 * Retrieves the current Request ID or generates a fallback if outside request scope.
 */
export function getCurrentRequestId(): string | undefined {
  return asyncLocalStorage.getStore()?.requestId;
}

/**
 * Retrieves the current Trace ID if available.
 */
export function getCurrentTraceId(): string | undefined {
  return asyncLocalStorage.getStore()?.traceId;
}

/**
 * Enriches the current context (e.g., after authentication middleware identifies user).
 */
export function updateContext(updates: Partial<RequestContext>): void {
  const store = asyncLocalStorage.getStore();
  if (store) {
    Object.assign(store, updates);
  }
}
