import { Request, Response } from "express";
import { EventService } from "../services/event.service";
import { InstitutionService } from "../services/institution.service";
import { z } from "zod";
import { EventStatus } from "@prisma/client";
import { getPrisma } from "../utils/db";
import { publicErrorMessage, respondWithError } from "../utils/http-error";

const ticketTierSchema = z.object({
  name: z.string().min(1, "Tier name is required"),
  description: z.string().optional(),
  price: z.number().int().min(0, "Price must be positive (in cents)"),
  capacity: z.number().int().min(1, "Capacity must be at least 1"),
});

const accessPolicySchema = z.object({
  policyType: z.enum(["PUBLIC", "INSTITUTION_ONLY", "INVITE_ONLY"]).default("PUBLIC"),
  allowedDomains: z.array(z.string()).default([]),
  requireVerifiedEmail: z.boolean().default(true),
  allowFreeTickets: z.boolean().default(false),
  customRestrictionMessage: z.string().optional(),
}).optional();

const createEventSchema = z.object({
  title: z.string().min(3, "Title must be at least 3 characters"),
  description: z.string().min(10, "Description must be at least 10 characters"),
  category: z.string().min(1, "Category is required"),
  locationType: z.enum(["VENUE", "ONLINE"]),
  venue: z.string().optional(),
  city: z.string().optional(),
  startsAt: z.string().min(1, "StartsAt must be a valid date"),
  endsAt: z.string().min(1, "EndsAt must be a valid date"),
  bannerUrl: z.string().optional(),
  ticketTiers: z.array(ticketTierSchema).min(1, "At least 1 ticket tier is required"),
  hasSeatingPlan: z.boolean().optional(),
  seatingRows: z.number().int().min(1).max(20).optional(),
  seatingCols: z.number().int().min(1).max(20).optional(),
  accessPolicy: accessPolicySchema,
});

const updateEventSchema = z.object({
  title: z.string().min(3, "Title must be at least 3 characters").optional(),
  description: z.string().min(10, "Description must be at least 10 characters").optional(),
  category: z.string().min(1, "Category is required").optional(),
  locationType: z.enum(["VENUE", "ONLINE"]).optional(),
  venue: z.string().optional(),
  city: z.string().optional(),
  startsAt: z.string().optional(),
  endsAt: z.string().optional(),
  bannerUrl: z.string().optional(),
  ticketTiers: z.array(
    z.object({
      id: z.string().optional(),
      name: z.string().min(1, "Tier name is required"),
      description: z.string().optional(),
      price: z.number().int().min(0),
      capacity: z.number().int().min(1),
    })
  ).optional(),
  hasSeatingPlan: z.boolean().optional(),
  seatingRows: z.number().int().min(1).max(20).optional(),
  seatingCols: z.number().int().min(1).max(20).optional(),
  accessPolicy: accessPolicySchema,
});

const lifecycleSchema = z.object({
  action: z.enum(["submit", "publish", "cancel"]),
});

export class EventController {
  private eventService = new EventService();
  private institutionService = new InstitutionService();

  getEvents = async (req: Request, res: Response) => {
    try {
      const parsedLimit = req.query.limit ? parseInt(req.query.limit as string) : 10;
      const parsedPage = req.query.page ? parseInt(req.query.page as string) : 1;

      // The public listing only ever shows published events; other states are reachable via the organizer routes.
      if (req.query.status !== undefined && !Object.values(EventStatus).includes(req.query.status as EventStatus)) {
        return res.status(400).json({ error: "Unknown status filter." });
      }
      const filters = {
        category: req.query.category as string,
        city: req.query.city as string,
        search: req.query.search as string,
        status: "PUBLISHED" as const,
        limit: Math.min(100, Math.max(1, isNaN(parsedLimit) ? 10 : parsedLimit)),
        page: Math.max(1, isNaN(parsedPage) ? 1 : parsedPage),
      };

      const result = await this.eventService.getEvents(filters);
      if (filters.status === "PUBLISHED") {
        // Identical for every visitor: let browsers/CDN reuse it briefly (the server also caches for 60 s)
        res.setHeader("Cache-Control", "public, max-age=10, stale-while-revalidate=30");
      }
      res.status(200).json(result);
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 500);
    }
  };

  getEventBySlug = async (req: Request, res: Response) => {
    try {
      const slug = req.params.slug;
      const event = await this.eventService.getEventBySlug(slug);
      res.status(200).json(event);
    } catch (err: unknown) {
      respondWithError(res, err, "Event not found", 404);
    }
  };

  checkEligibility = async (req: Request, res: Response) => {
    try {
      const eventId = req.params.eventId || req.params.id;
      const event = await this.eventService.getEventBySlug(eventId).catch(() => null);
      if (!event) {
        return res.status(404).json({ error: "Event not found" });
      }

      const userEmail = req.user ? req.user.email : null;
      const eligibility = await this.institutionService.evaluateEligibility(
        userEmail,
        event.accessPolicy
      );

      res.status(200).json(eligibility);
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 500);
    }
  };

  createEvent = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Unauthenticated" });
      }

      const body = createEventSchema.parse(req.body);
      const event = await this.eventService.createEvent(req.user.id, {
        title: body.title,
        description: body.description,
        category: body.category,
        locationType: body.locationType,
        venue: body.venue,
        city: body.city,
        startsAt: body.startsAt,
        endsAt: body.endsAt,
        bannerUrl: body.bannerUrl || undefined,
        ticketTiers: body.ticketTiers,
        hasSeatingPlan: body.hasSeatingPlan,
        seatingRows: body.seatingRows,
        seatingCols: body.seatingCols,
        accessPolicy: body.accessPolicy,
      });

      res.status(201).json(event);
    } catch (err: unknown) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ error: err.issues[0].message });
      } else {
        respondWithError(res, err, "Failed to create event", 400);
      }
    }
  };

  getOrganizerEvents = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Unauthenticated" });
      }

      const list = await this.eventService.getOrganizerEvents(req.user.id);
      res.status(200).json(list);
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 400);
    }
  };

  updateEvent = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Unauthenticated" });
      }

      const eventId = req.params.id;
      const body = updateEventSchema.parse(req.body);

      const updated = await this.eventService.updateEvent(req.user.id, eventId, body);
      res.status(200).json(updated);
    } catch (err: unknown) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ error: err.issues[0].message });
      } else {
        respondWithError(res, err, "Failed to update event", 400);
      }
    }
  };

  changeLifecycle = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Unauthenticated" });
      }

      const { action } = lifecycleSchema.parse(req.body);
      const eventId = req.params.id;

      const updated = await this.eventService.transitionLifecycle(req.user.id, eventId, action);
      res.status(200).json(updated);
    } catch (err: unknown) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ error: err.issues[0].message });
      } else {
        respondWithError(res, err, "Request failed. Please try again.", 400);
      }
    }
  };

  getOccupiedSeats = async (req: Request, res: Response) => {
    try {
      const eventId = req.params.eventId;
      const prisma = getPrisma();

      const bookings = await prisma.booking.findMany({
        where: {
          eventId,
          status: { in: ["RESERVED", "PENDING", "CONFIRMED"] }
        },
        include: {
          items: true
        }
      });

      const occupied: string[] = [];
      for (const b of bookings) {
        for (const item of b.items) {
          if (item.seatNumbers) {
            const seats = item.seatNumbers.split(",").map((s: string) => s.trim());
            occupied.push(...seats);
          }
        }
      }

      res.status(200).json(Array.from(new Set(occupied)));
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 500);
    }
  };

  getReviews = async (req: Request, res: Response) => {
    try {
      const eventId = req.params.eventId;
      const prisma = getPrisma();
      const parsedLimit = req.query.limit ? parseInt(req.query.limit as string) : 50;
      const parsedPage = req.query.page ? parseInt(req.query.page as string) : 1;
      const limit = Math.min(100, Math.max(1, isNaN(parsedLimit) ? 50 : parsedLimit));
      const page = Math.max(1, isNaN(parsedPage) ? 1 : parsedPage);

      const reviews = await prisma.review.findMany({
        where: { eventId },
        include: {
          user: true
        },
        orderBy: { createdAt: "desc" },
        take: limit,
        skip: (page - 1) * limit,
      });

      const mapped = reviews.map((r: any) => ({
        id: r.id,
        eventId: r.eventId,
        userId: r.userId,
        userName: r.user.fullName,
        userAvatarUrl: r.user.avatarUrl,
        rating: r.rating,
        comment: r.comment,
        createdAt: r.createdAt.toISOString()
      }));

      res.status(200).json(mapped);
    } catch (err: unknown) {
      respondWithError(res, err, "Request failed. Please try again.", 500);
    }
  };

  getReviewEligibility = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(200).json({
          eligible: false,
          hasReviewed: false,
          reason: "Sign in to verify check-in status for reviews.",
        });
      }

      const eventId = req.params.eventId;
      const prisma = getPrisma();

      // Check if user already reviewed
      const existing = await prisma.review.findUnique({
        where: {
          eventId_userId: {
            eventId,
            userId: req.user.id,
          },
        },
      });

      if (existing) {
        return res.status(200).json({
          eligible: false,
          hasReviewed: true,
          reason: "You have already shared a review for this event.",
        });
      }

      // Check if attendee completed check-in via security gate scanner
      const scannedBooking = await prisma.booking.findFirst({
        where: {
          eventId,
          userId: req.user.id,
          status: "CONFIRMED",
          attendance: {
            scannedAt: { not: null },
          },
        },
      });

      if (scannedBooking) {
        return res.status(200).json({
          eligible: true,
          hasReviewed: false,
        });
      }

      return res.status(200).json({
        eligible: false,
        hasReviewed: false,
        reason: "Only verified attendees who successfully checked in via the Security Gate Scanner are eligible to leave a review.",
      });
    } catch (err: unknown) {
      res.status(200).json({
        eligible: false,
        hasReviewed: false,
        reason: "Could not verify review eligibility.",
      });
    }
  };

  createReview = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Unauthenticated" });
      }

      const eventId = req.params.eventId;
      const { rating, comment } = z.object({
        rating: z.number().int().min(1).max(5),
        comment: z.string().min(3, "Review must be at least 3 characters")
      }).parse(req.body);

      const prisma = getPrisma();

      const scannedBooking = await prisma.booking.findFirst({
        where: {
          eventId,
          userId: req.user.id,
          status: "CONFIRMED",
          attendance: {
            scannedAt: { not: null }
          }
        }
      });

      if (!scannedBooking) {
        return res.status(403).json({
          error: "Only verified attendees who successfully checked in via the Security Gate Scanner are unlocked to leave a rating and review."
        });
      }

      const existing = await prisma.review.findUnique({
        where: {
          eventId_userId: {
            eventId,
            userId: req.user.id
          }
        }
      });

      if (existing) {
        return res.status(400).json({ error: "You have already left a review for this event." });
      }

      const created = await prisma.review.create({
        data: {
          eventId,
          userId: req.user.id,
          rating,
          comment
        },
        include: { user: true }
      });

      res.status(201).json({
        id: created.id,
        eventId: created.eventId,
        userId: created.userId,
        userName: created.user.fullName,
        userAvatarUrl: created.user.avatarUrl,
        rating: created.rating,
        comment: created.comment,
        createdAt: created.createdAt.toISOString()
      });
    } catch (err: unknown) {
      if (err instanceof z.ZodError) {
        res.status(400).json({ error: err.issues[0].message });
      } else {
        respondWithError(res, err, "Request failed. Please try again.", 400);
      }
    }
  };

  deleteEvent = async (req: Request, res: Response) => {
    try {
      if (!req.user) {
        return res.status(401).json({ error: "Unauthenticated" });
      }

      const eventId = req.params.id || req.params.eventId;
      await this.eventService.deleteEvent(req.user.id, eventId);

      res.status(200).json({ success: true, message: "Event successfully deleted." });
    } catch (err: unknown) {
      // Typed errors carry their own status (403 Forbidden, 404 Not Found)
      respondWithError(res, err, "Failed to delete event.", 400);
    }
  };
}
