import { getPrisma } from "../utils/db";
import { AccessPolicyType, Event, EventStatus, LocationType, TicketTier } from "@prisma/client";

export interface EventQueryFilters {
  category?: string;
  city?: string;
  search?: string;
  status?: string;
  limit?: number;
  page?: number;
  includePassed?: boolean;
}

export class EventRepository {
  private prisma = getPrisma();

  async findMany(filters: EventQueryFilters = {}) {
    const { category, city, search, status = "PUBLISHED", limit = 12, page = 1, includePassed = false } = filters;
    const skip = (page - 1) * limit;

    const where: any = {
      status,
    };

    // If querying public published events, only show future/active events that haven't passed
    if (!includePassed && (status === "PUBLISHED" || !status)) {
      where.endsAt = { gte: new Date() };
    }

    if (category && category !== "All") {
      where.category = { equals: category };
    }

    if (city && city !== "All") {
      where.city = { equals: city };
    }

    if (search) {
      where.OR = [
        { title: { contains: search } },
        { description: { contains: search } },
        { venue: { contains: search } },
      ];
    }

    const [events, total] = await this.prisma.$transaction([
      this.prisma.event.findMany({
        where,
        include: {
          organizer: {
            include: { user: true },
          },
          ticketTiers: true,
          accessPolicy: true,
        },
        orderBy: [{ startsAt: "asc" }],
        take: limit,
        skip,
      }),
      this.prisma.event.count({ where }),
    ]);

    return { events, total };
  }

  async findBySlug(slug: string) {
    return this.prisma.event.findUnique({
      where: { slug },
      include: {
        organizer: {
          include: { user: true },
        },
        ticketTiers: true,
        accessPolicy: true,
      },
    });
  }

  async findById(id: string) {
    return this.prisma.event.findUnique({
      where: { id },
      include: {
        organizer: {
          include: { user: true },
        },
        ticketTiers: true,
        accessPolicy: true,
      },
    });
  }

  async createEvent(data: {
    organizerId: string;
    title: string;
    slug: string;
    description: string;
    category: string;
    locationType: LocationType;
    venue?: string | null;
    city?: string | null;
    startsAt: Date;
    endsAt: Date;
    bannerUrl?: string | null;
    status?: EventStatus;
    hasSeatingPlan?: boolean;
    seatingRows?: number;
    seatingCols?: number;
    ticketTiers: Array<{
      name: string;
      description?: string;
      price: number;
      capacity: number;
    }>;
    accessPolicy?: {
      policyType: AccessPolicyType;
      allowedDomains: string[];
      requireVerifiedEmail?: boolean;
      allowFreeTickets?: boolean;
      customRestrictionMessage?: string | null;
    };
  }) {
    return this.prisma.$transaction(async (tx) => {
      const event = await tx.event.create({
        data: {
          organizerId: data.organizerId,
          title: data.title,
          slug: data.slug,
          description: data.description,
          category: data.category,
          locationType: data.locationType,
          venue: data.venue || null,
          city: data.city || null,
          startsAt: data.startsAt,
          endsAt: data.endsAt,
          bannerUrl: data.bannerUrl || null,
          status: data.status || "DRAFT",
          hasSeatingPlan: data.hasSeatingPlan ?? false,
          seatingRows: data.seatingRows ?? 10,
          seatingCols: data.seatingCols ?? 10,
        },
      });

      const tiers = await Promise.all(
        data.ticketTiers.map((tier) =>
          tx.ticketTier.create({
            data: {
              eventId: event.id,
              name: tier.name,
              description: tier.description || null,
              price: tier.price,
              capacity: tier.capacity,
            },
          })
        )
      );

      let policy = null;
      if (data.accessPolicy) {
        policy = await tx.eventAccessPolicy.create({
          data: {
            eventId: event.id,
            policyType: data.accessPolicy.policyType || "PUBLIC",
            allowedDomains: JSON.stringify(data.accessPolicy.allowedDomains || []),
            requireVerifiedEmail: data.accessPolicy.requireVerifiedEmail ?? true,
            allowFreeTickets: data.accessPolicy.allowFreeTickets ?? false,
            customRestrictionMessage: data.accessPolicy.customRestrictionMessage || null,
          },
        });
      }

      return { ...event, ticketTiers: tiers, accessPolicy: policy };
    });
  }

  async updateStatus(eventId: string, status: EventStatus): Promise<Event> {
    return this.prisma.event.update({
      where: { id: eventId },
      data: { status },
    });
  }

  async updateEvent(
    eventId: string,
    data: {
      title?: string;
      description?: string;
      category?: string;
      locationType?: string;
      venue?: string | null;
      city?: string | null;
      startsAt?: Date;
      endsAt?: Date;
      bannerUrl?: string | null;
      status?: EventStatus;
      hasSeatingPlan?: boolean;
      seatingRows?: number;
      seatingCols?: number;
      ticketTiers?: Array<{
        id?: string;
        name: string;
        description?: string;
        price: number;
        capacity: number;
      }>;
      accessPolicy?: {
        policyType: AccessPolicyType;
        allowedDomains: string[];
        requireVerifiedEmail?: boolean;
        allowFreeTickets?: boolean;
        customRestrictionMessage?: string | null;
      };
    }
  ) {
    return this.prisma.$transaction(async (tx) => {
      const updateData: any = {};
      if (data.title !== undefined) updateData.title = data.title;
      if (data.description !== undefined) updateData.description = data.description;
      if (data.category !== undefined) updateData.category = data.category;
      if (data.locationType !== undefined) updateData.locationType = data.locationType;
      if (data.venue !== undefined) updateData.venue = data.venue;
      if (data.city !== undefined) updateData.city = data.city;
      if (data.startsAt !== undefined) updateData.startsAt = data.startsAt;
      if (data.endsAt !== undefined) updateData.endsAt = data.endsAt;
      if (data.bannerUrl !== undefined) updateData.bannerUrl = data.bannerUrl;
      if (data.status !== undefined) updateData.status = data.status;
      if (data.hasSeatingPlan !== undefined) updateData.hasSeatingPlan = data.hasSeatingPlan;
      if (data.seatingRows !== undefined) updateData.seatingRows = data.seatingRows;
      if (data.seatingCols !== undefined) updateData.seatingCols = data.seatingCols;

      await tx.event.update({
        where: { id: eventId },
        data: updateData,
      });

      if (data.ticketTiers && data.ticketTiers.length > 0) {
        // Delete unsold ticket tiers that are not included in the updated list
        const providedIds = data.ticketTiers.map((t) => t.id).filter(Boolean) as string[];
        await tx.ticketTier.deleteMany({
          where: {
            eventId,
            sold: 0,
            reserved: 0,
            id: { notIn: providedIds },
          },
        });

        for (const tier of data.ticketTiers) {
          if (tier.id) {
            const existing = await tx.ticketTier.findUnique({ where: { id: tier.id } });
            if (existing) {
              await tx.ticketTier.update({
                where: { id: tier.id },
                data: {
                  name: tier.name,
                  description: tier.description || null,
                  price: tier.price,
                  capacity: tier.capacity,
                },
              });
              continue;
            }
          }
          await tx.ticketTier.create({
            data: {
              eventId,
              name: tier.name,
              description: tier.description || null,
              price: tier.price,
              capacity: tier.capacity,
            },
          });
        }
      }

      if (data.accessPolicy) {
        await tx.eventAccessPolicy.upsert({
          where: { eventId },
          create: {
            eventId,
            policyType: data.accessPolicy.policyType || "PUBLIC",
            allowedDomains: JSON.stringify(data.accessPolicy.allowedDomains || []),
            requireVerifiedEmail: data.accessPolicy.requireVerifiedEmail ?? true,
            allowFreeTickets: data.accessPolicy.allowFreeTickets ?? false,
            customRestrictionMessage: data.accessPolicy.customRestrictionMessage || null,
          },
          update: {
            policyType: data.accessPolicy.policyType,
            allowedDomains: JSON.stringify(data.accessPolicy.allowedDomains || []),
            requireVerifiedEmail: data.accessPolicy.requireVerifiedEmail ?? true,
            allowFreeTickets: data.accessPolicy.allowFreeTickets ?? false,
            customRestrictionMessage: data.accessPolicy.customRestrictionMessage || null,
          },
        });
      }

      return tx.event.findUnique({
        where: { id: eventId },
        include: {
          organizer: { include: { user: true } },
          ticketTiers: true,
          accessPolicy: true,
        },
      });
    });
  }

  async getOrganizerEvents(organizerId: string) {
    return this.prisma.event.findMany({
      where: { organizerId },
      include: {
        ticketTiers: true,
        accessPolicy: true,
      },
      orderBy: { createdAt: "desc" },
    });
  }

  async incrementTicketSales(tierId: string, quantity: number, transactionContext?: any) {
    const tx = transactionContext || this.prisma;
    return tx.ticketTier.update({
      where: { id: tierId },
      data: {
        sold: { increment: quantity },
        reserved: { decrement: quantity },
      },
    });
  }

  async deleteEvent(eventId: string): Promise<void> {
    await this.prisma.$transaction(async (tx) => {
      // Find all bookings for this event
      const bookings = await tx.booking.findMany({
        where: { eventId },
        select: { id: true },
      });
      const bookingIds = bookings.map((b) => b.id);

      if (bookingIds.length > 0) {
        // Delete attendances
        await tx.attendance.deleteMany({
          where: { bookingId: { in: bookingIds } },
        });

        // Delete ticket transfers
        await tx.ticketTransfer.deleteMany({
          where: { bookingId: { in: bookingIds } },
        });

        // Delete tickets
        await tx.ticket.deleteMany({
          where: { bookingId: { in: bookingIds } },
        });

        // Delete split shares
        await tx.bookingSplitShare.deleteMany({
          where: { bookingId: { in: bookingIds } },
        });

        // Delete payment transactions
        await tx.payment.deleteMany({
          where: { bookingId: { in: bookingIds } },
        });

        // Delete booking items
        await tx.bookingItem.deleteMany({
          where: { bookingId: { in: bookingIds } },
        });

        // Delete bookings
        await tx.booking.deleteMany({
          where: { id: { in: bookingIds } },
        });
      }

      // Delete seats
      await tx.eventSeat.deleteMany({
        where: { eventId },
      });

      // Delete promo codes
      await tx.promoCode.deleteMany({
        where: { eventId },
      });

      // Delete reviews
      await tx.review.deleteMany({
        where: { eventId },
      });

      // Delete ticket tiers
      await tx.ticketTier.deleteMany({
        where: { eventId },
      });

      // Delete event access policy
      await tx.eventAccessPolicy.deleteMany({
        where: { eventId },
      });

      // Delete event
      await tx.event.delete({
        where: { id: eventId },
      });
    });
  }
}
