import { Request, Response, NextFunction } from "express";
import { AppError } from "../errors/app-error";
import { logger } from "../utils/logger";
import { metrics, normalizeRoute } from "../utils/metrics";
import { ZodError } from "zod";

export function errorHandler(
  err: any,
  req: Request,
  res: Response,
  next: NextFunction
) {
  const requestId = req.id;
  const traceId = req.traceId;
  const normalized = normalizeRoute(req.path);

  // 1. Handle known operational AppError hierarchy
  if (err instanceof AppError) {
    logger.warn(`[Operational Error] ${err.errorCode}: ${err.message}`, {
      requestId,
      traceId,
      statusCode: err.statusCode,
      errorCode: err.errorCode,
      path: req.path,
      normalizedRoute: normalized,
      method: req.method,
    });

    return res.status(err.statusCode).json({
      error: {
        code: err.errorCode,
        message: err.message,
        requestId,
      },
    });
  }

  // 2. Handle Zod schema validation errors
  if (err instanceof ZodError) {
    const issues = err.issues || [];
    const formattedMessage = issues.map((e: any) => e.message).join("; ") || "Validation failed";
    logger.warn(`[Validation Error]: ${formattedMessage}`, {
      requestId,
      traceId,
      path: req.path,
      normalizedRoute: normalized,
      method: req.method,
      issues,
    });

    return res.status(400).json({
      error: {
        code: "VALIDATION_ERROR",
        message: formattedMessage,
        requestId,
      },
    });
  }

  // 3. Handle JWT errors
  if (err.name === "JsonWebTokenError" || err.name === "TokenExpiredError") {
    return res.status(401).json({
      error: {
        code: "UNAUTHENTICATED",
        message: "Invalid or expired authentication token.",
        requestId,
      },
    });
  }

  // 4. Handle Prisma Known Request Errors safely
  if (err.code && typeof err.code === "string" && err.code.startsWith("P")) {
    logger.error(`[Prisma Database Error] Code ${err.code}: ${err.message}`, {
      requestId,
      traceId,
      code: err.code,
      path: req.path,
      normalizedRoute: normalized,
      method: req.method,
      stack: process.env.NODE_ENV !== "production" ? err.stack : undefined,
    });

    let message = "A database constraint error occurred.";
    let statusCode = 400;
    let errorCode = "DATABASE_ERROR";

    if (err.code === "P2002") {
      message = "A record with this unique value already exists.";
      statusCode = 409;
      errorCode = "CONFLICT";
    } else if (err.code === "P2025") {
      message = "The requested database record was not found.";
      statusCode = 404;
      errorCode = "NOT_FOUND";
    }

    return res.status(statusCode).json({
      error: {
        code: errorCode,
        message,
        requestId,
      },
    });
  }

  // 5. Fallback for unhandled 500 internal errors (Formatted for Google Cloud Error Reporting)
  logger.error(`[Unhandled Internal Error] ${err?.message || "Unknown error"}`, {
    requestId,
    traceId,
    stack: err?.stack,
    path: req.path,
    normalizedRoute: normalized,
    method: req.method,
    "@type": "type.googleapis.com/google.devtools.clouderrorreporting.v1beta1.ReportedErrorEvent",
    context: {
      httpRequest: {
        method: req.method,
        url: req.originalUrl || req.path,
        userAgent: req.headers["user-agent"],
        responseStatusCode: 500,
        remoteIp: req.ip,
      },
    },
  });

  const isProduction = process.env.NODE_ENV === "production";
  const safeMessage = isProduction
    ? "An internal server error occurred."
    : err?.message || "An unexpected error occurred.";

  return res.status(err.statusCode || 500).json({
    error: {
      code: "INTERNAL_ERROR",
      message: safeMessage,
      requestId,
    },
  });
}
