import { getPrisma } from "../utils/db";
import { Ticket, TicketTransfer, AttendanceLog } from "@prisma/client";

export class TicketRepository {
  private prisma: any;

  constructor(prismaClient?: any) {
    this.prisma = prismaClient || getPrisma();
  }

  async findById(ticketId: string) {
    return this.prisma.ticket.findUnique({
      where: { id: ticketId },
      include: {
        booking: {
          include: {
            event: true,
            user: true,
          },
        },
        ticketTier: true,
        ownerUser: true,
        scannedByUser: true,
        transfers: {
          include: {
            senderUser: true,
            claimedByUser: true,
          },
        },
      },
    });
  }

  async findByTicketNumber(ticketNumber: string) {
    return this.prisma.ticket.findUnique({
      where: { ticketNumber },
      include: {
        booking: {
          include: {
            event: true,
            user: true,
          },
        },
        ticketTier: true,
        ownerUser: true,
      },
    });
  }

  async findByQrToken(qrToken: string) {
    const trimmed = qrToken.trim();
    const upper = trimmed.toUpperCase();

    // Lookup ticket by cryptographic qrToken, ticketNumber (used as baseRef for dynamic tokens), or attendance qrHash.
    // Unrelated public identifiers (booking IDs, invoice numbers, raw database IDs) are strictly disallowed.
    return this.prisma.ticket.findFirst({
      where: {
        OR: [
          { qrToken: trimmed },
          { qrToken: upper },
          { ticketNumber: trimmed },
          { ticketNumber: upper },
          { booking: { attendance: { qrHash: trimmed } } },
          { booking: { attendance: { qrHash: upper } } },
        ],
      },
      include: {
        booking: {
          include: {
            event: true,
            user: true,
            attendance: true,
          },
        },
        ticketTier: true,
        ownerUser: true,
      },
    });
  }

  async findByUserId(userId: string) {
    return this.prisma.ticket.findMany({
      where: { ownerUserId: userId },
      include: {
        booking: {
          include: {
            event: true,
          },
        },
        ticketTier: true,
        ownerUser: true,
        transfers: {
          include: {
            senderUser: true,
            claimedByUser: true,
          },
        },
      },
      orderBy: { createdAt: "desc" },
    });
  }

  async findByBookingId(bookingId: string) {
    return this.prisma.ticket.findMany({
      where: { bookingId },
      include: {
        ticketTier: true,
        ownerUser: true,
      },
      orderBy: { createdAt: "asc" },
    });
  }

  async findByEventId(eventId: string) {
    return this.prisma.ticket.findMany({
      where: {
        booking: {
          eventId,
        },
      },
      include: {
        ticketTier: true,
        ownerUser: true,
        booking: {
          include: {
            user: true,
          },
        },
      },
      orderBy: { createdAt: "desc" },
    });
  }

  async logAttendanceAttempt(data: {
    ticketId?: string;
    ticketNumber?: string;
    eventId: string;
    scannerUserId: string;
    scanOutcome: string;
    ipAddress?: string;
    userAgent?: string;
  }): Promise<AttendanceLog> {
    return this.prisma.attendanceLog.create({
      data: {
        ticketId: data.ticketId || null,
        ticketNumber: data.ticketNumber || null,
        eventId: data.eventId,
        scannerUserId: data.scannerUserId,
        scanOutcome: data.scanOutcome,
        ipAddress: data.ipAddress || null,
        userAgent: data.userAgent || null,
      },
    });
  }
}
