function createTransporter(account: SmtpAccount): Transporter {
  return nodemailer.createTransport({
    host: "smtp.gmail.com",
    port: 587,
    secure: false,
    auth: {
      user: account.user,
      pass: account.pass,
    },
    connectionTimeout: 15000,
    greetingTimeout: 15000,
    socketTimeout: 20000,
  });
}

function getTransporter(accountKey: string): { transporter: Transporter; account: SmtpAccount } {
  const acc = accounts[accountKey] || accounts.AUTH;
  if (!acc.transport) {
    acc.transport = createTransporter(acc);
  }
  return { transporter: acc.transport, account: acc };
}

export interface SendMailOptions {
  stage?: 1 | 2 | 3 | "AUTH";
  to: string;
  subject: string;
  html: string;
  text?: string;
}

export async function sendVentureMail(options: SendMailOptions): Promise<{ success: boolean; messageId?: string; sentVia: string; error?: string }> {
  const primaryKey = options.stage === 1 ? "STAGE_1" : options.stage === 2 ? "STAGE_2" : options.stage === 3 ? "STAGE_3" : "AUTH";
  
  // Ordered fallback keys if primary throws an authentication or rate limit error
  const fallbackOrder = [primaryKey, "STAGE_1", "STAGE_3", "AUTH"].filter((v, i, a) => a.indexOf(v) === i);

  let lastError = "";

  for (const key of fallbackOrder) {
    try {
      const { transporter, account } = getTransporter(key);
      const info = await transporter.sendMail({
        from: account.from,
        to: options.to,
        subject: options.subject,
        html: options.html,
        text: options.text || options.subject,
      });

      logger.info(`[MULTI-SMTP] Dispatched to ${options.to} via ${account.name} (${account.user}) [MsgId: ${info.messageId}]`);
      return {
        success: true,
        messageId: info.messageId,
        sentVia: account.user,
      };
    } catch (err: unknown) {
      lastError = errorMessage(err);
      logger.warn(`[MULTI-SMTP] Account ${key} failed to send to ${options.to}: ${lastError}. Attempting fallback...`);
    }
  }

  logger.error(`[MULTI-SMTP ERROR] All fallback transporters failed for ${options.to}: ${lastError}`);
  return {
    success: false,
    error: lastError,
    sentVia: "FAILED",
  };
}
