import { logger } from "./logger";
import { metrics } from "./metrics";

/**
 * Error handler for side effects that must not fail the request (cache cleanup, lock release, hold rollback).
 * The failure is never silent: it is logged and counted so leaks and dead dependencies show up in monitoring.
 *
 *   await redis.del(key).catch(bestEffort("redis.del seat lock"));
 */
export const bestEffort = (operation: string) => (err: unknown): void => {
  logger.warn(`Best-effort step failed: ${operation}`, { message: err instanceof Error ? err.message : String(err) });
  metrics.incrementCounter("best_effort_failures_total", operation);
};
