import { getPrisma } from "../utils/db";
import { WhatsAppService } from "./whatsapp.service";

import { BadRequestError, ConflictError, ForbiddenError, NotFoundError } from "../errors/app-error";
export interface CancellationPolicyAssessment {
  canCancel: boolean;
  tier: "STANDARD_TIER" | "MID_TIER" | "LAST_MINUTE_TIER" | "NON_REFUNDABLE" | "FREE_TICKET";
  feePercentage: number;
  refundPercentage: number;
  originalAmount: number; // in paise
  cancellationFee: number; // in paise
  refundAmount: number; // in paise
  hoursUntilEvent: number;
  policySummary: string;
  reason?: string;
}

export class WalletService {
  private prisma = getPrisma();

  /**
   * Retrieves or creates the user's Happenins Wallet.
   */
  async getOrCreateWallet(userId: string) {
    let wallet = await this.prisma.wallet.findUnique({
      where: { userId },
      include: {
        transactions: {
          orderBy: { createdAt: "desc" },
          take: 50,
        },
      },
    });

    if (!wallet) {
      wallet = await this.prisma.wallet.create({
        data: {
          userId,
          balance: 0,
        },
        include: {
          transactions: true,
        },
      });
    }

    return wallet;
  }

  /**
   * Get wallet balance for a user.
   */
  async getWalletBalance(userId: string): Promise<number> {
    const wallet = await this.getOrCreateWallet(userId);
    return wallet.balance;
  }

  /**
   * Evaluates the cancellation policy and calculates fees and refund for a booking.
   */
  async evaluateCancellationPolicy(bookingId: string, userId: string): Promise<CancellationPolicyAssessment> {
    const booking = await this.prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        event: true,
        items: true,
        attendance: true,
      },
    });

    if (!booking) {
      throw new NotFoundError("Booking not found.");
    }

    if (booking.userId !== userId) {
      throw new ForbiddenError("Unauthorized to access this booking.");
    }

    if (booking.status === "CANCELLED") {
      throw new ConflictError("Booking is already cancelled.");
    }

    if (booking.status === "EXPIRED") {
      throw new ConflictError("Booking has expired.");
    }

    if (booking.status !== "CONFIRMED") {
      throw new ConflictError(`Only confirmed bookings can be evaluated for cancellation. Current status: ${booking.status}`);
    }

    if (booking.attendance?.scannedAt) {
      return {
        canCancel: false,
        tier: "NON_REFUNDABLE",
        feePercentage: 100,
        refundPercentage: 0,
        originalAmount: booking.totalAmount,
        cancellationFee: booking.totalAmount,
        refundAmount: 0,
        hoursUntilEvent: 0,
        policySummary: "Tickets already scanned at the venue cannot be cancelled.",
        reason: "Ticket already checked in.",
      };
    }

    const startsAt = booking.event.startsAt ? new Date(booking.event.startsAt) : new Date();
    const now = new Date();
    const diffMs = startsAt.getTime() - now.getTime();
    const hoursUntilEvent = Math.max(0, diffMs / (1000 * 60 * 60));

    if (booking.totalAmount === 0) {
      return {
        canCancel: true,
        tier: "FREE_TICKET",
        feePercentage: 0,
        refundPercentage: 100,
        originalAmount: 0,
        cancellationFee: 0,
        refundAmount: 0,
        hoursUntilEvent: Math.round(hoursUntilEvent * 10) / 10,
        policySummary: "Free registration cancelled with no charges.",
      };
    }

    if (diffMs <= 0) {
      return {
        canCancel: false,
        tier: "NON_REFUNDABLE",
        feePercentage: 100,
        refundPercentage: 0,
        originalAmount: booking.totalAmount,
        cancellationFee: booking.totalAmount,
        refundAmount: 0,
        hoursUntilEvent: 0,
        policySummary: "Event has already started or ended. Tickets are non-refundable.",
        reason: "Event has already commenced.",
      };
    }

    if (hoursUntilEvent > 48) {
      // > 48 hours: 10% fee, 90% refund
      const fee = Math.round(booking.totalAmount * 0.10);
      const refund = booking.totalAmount - fee;
      return {
        canCancel: true,
        tier: "STANDARD_TIER",
        feePercentage: 10,
        refundPercentage: 90,
        originalAmount: booking.totalAmount,
        cancellationFee: fee,
        refundAmount: refund,
        hoursUntilEvent: Math.round(hoursUntilEvent * 10) / 10,
        policySummary: "More than 48 hrs before event: 90% refunded to Happenins Wallet (10% processing fee deducted).",
      };
    } else if (hoursUntilEvent >= 24) {
      // 24 - 48 hours: 25% fee, 75% refund
      const fee = Math.round(booking.totalAmount * 0.25);
      const refund = booking.totalAmount - fee;
      return {
        canCancel: true,
        tier: "MID_TIER",
        feePercentage: 25,
        refundPercentage: 75,
        originalAmount: booking.totalAmount,
        cancellationFee: fee,
        refundAmount: refund,
        hoursUntilEvent: Math.round(hoursUntilEvent * 10) / 10,
        policySummary: "24-48 hrs before event: 75% refunded to Happenins Wallet (25% cancellation charge deducted).",
      };
    } else if (hoursUntilEvent >= 4) {
      // 4 - 24 hours: 50% fee, 50% refund
      const fee = Math.round(booking.totalAmount * 0.50);
      const refund = booking.totalAmount - fee;
      return {
        canCancel: true,
        tier: "LAST_MINUTE_TIER",
        feePercentage: 50,
        refundPercentage: 50,
        originalAmount: booking.totalAmount,
        cancellationFee: fee,
        refundAmount: refund,
        hoursUntilEvent: Math.round(hoursUntilEvent * 10) / 10,
        policySummary: "4-24 hrs before event: 50% refunded to Happenins Wallet (50% late cancellation fee deducted).",
      };
    } else {
      // < 4 hours: non-refundable
      return {
        canCancel: false,
        tier: "NON_REFUNDABLE",
        feePercentage: 100,
        refundPercentage: 0,
        originalAmount: booking.totalAmount,
        cancellationFee: booking.totalAmount,
        refundAmount: 0,
        hoursUntilEvent: Math.round(hoursUntilEvent * 10) / 10,
        policySummary: "Cancellations within 4 hours of event start are non-refundable according to Happenins Cancellation Policy.",
        reason: "Less than 4 hours remaining until event starts.",
      };
    }
  }

  /**
   * Executes transactional booking cancellation and credits refund amount to Happenins Wallet.
   */
  async cancelBookingAndRefundToWallet(userId: string, bookingId: string, reason?: string) {
    const assessment = await this.evaluateCancellationPolicy(bookingId, userId);
    if (!assessment.canCancel) {
      throw new BadRequestError(assessment.reason || assessment.policySummary || "This booking cannot be cancelled.");
    }

    return await this.prisma.$transaction(async (tx) => {
      // 1. Fetch booking with items
      const booking = await tx.booking.findUnique({
        where: { id: bookingId },
        include: {
          items: true,
          event: true,
          user: true,
        },
      });

      if (!booking) {
        throw new NotFoundError("Booking record not found.");
      }

      if (booking.status !== "CONFIRMED") {
        throw new BadRequestError("Booking is no longer in confirmed state.");
      }

      // 2. Mark booking as CANCELLED with fee and refund fields
      const updatedBooking = await tx.booking.update({
        where: { id: bookingId },
        data: {
          status: "CANCELLED",
          cancelledAt: new Date(),
          cancellationFee: assessment.cancellationFee,
          refundAmount: assessment.refundAmount,
          cancelledReason: reason || assessment.policySummary,
        },
      });

      // 3. Mark individual tickets as CANCELLED
      await tx.ticket.updateMany({
        where: { bookingId },
        data: { status: "CANCELLED" },
      });

      // 4. Release held/sold seats back to AVAILABLE
      await tx.eventSeat.updateMany({
        where: { bookingId },
        data: {
          status: "AVAILABLE",
          bookingId: null,
          heldUntil: null,
        },
      });

      // 5. Restore ticket tier capacities (decrement sold)
      for (const item of booking.items) {
        await tx.ticketTier.update({
          where: { id: item.ticketTierId },
          data: {
            sold: { decrement: item.quantity },
          },
        });
      }

      // 6. Credit Happenins Wallet if refundAmount > 0
      let wallet = await tx.wallet.findUnique({
        where: { userId },
      });

      if (!wallet) {
        wallet = await tx.wallet.create({
          data: {
            userId,
            balance: 0,
          },
        });
      }

      let newBalance = wallet.balance;
      if (assessment.refundAmount > 0) {
        newBalance = wallet.balance + assessment.refundAmount;

        await tx.wallet.update({
          where: { id: wallet.id },
          data: {
            balance: newBalance,
          },
        });

        await tx.walletTransaction.create({
          data: {
            walletId: wallet.id,
            type: "CREDIT",
            reason: "TICKET_CANCELLATION",
            amount: assessment.refundAmount,
            balanceAfter: newBalance,
            description: `Refund for cancelled booking #${booking.invoiceNumber} (${booking.event.title}). Deducted fee: ₹${(assessment.cancellationFee / 100).toFixed(2)}`,
            bookingId: booking.id,
            referenceId: booking.invoiceNumber,
          },
        });
      }

      // 7. Dispatch WhatsApp Cancellation & Wallet Credit Notification
      const customAppUrl = process.env.APP_URL || "https://happenins.com";
      const whatsappMsg = WhatsAppService.formatCancellationNotification(
        booking,
        assessment.refundAmount,
        assessment.cancellationFee,
        newBalance,
        customAppUrl
      );

      const targetPhone = (booking.user as any)?.phone || WhatsAppService.SENDER_NUMBER;
      await WhatsAppService.dispatchWhatsAppNotification(
        targetPhone,
        whatsappMsg,
        "BOOKING_CANCELLATION",
        { bookingId: booking.id, invoiceNumber: booking.invoiceNumber, refundAmount: assessment.refundAmount }
      );

      return {
        booking: updatedBooking,
        cancellationAssessment: assessment,
        walletBalance: newBalance,
        whatsappMessage: whatsappMsg,
      };
    });
  }

  /**
   * Applies Happenins Wallet balance during ticket booking/checkout.
   * Debits the wallet and records a transaction.
   */
  async applyWalletDebit(userId: string, amountToDebit: number, bookingId: string, invoiceNumber: string, eventTitle: string) {
    if (amountToDebit <= 0) return 0;

    return await this.prisma.$transaction(async (tx) => {
      const wallet = await tx.wallet.findUnique({
        where: { userId },
      });

      if (!wallet) {
        throw new NotFoundError("Happenins Wallet not found for user.");
      }

      if (wallet.balance < amountToDebit) {
        throw new BadRequestError(`Insufficient Happenins Wallet balance. Available: ₹${(wallet.balance / 100).toFixed(2)}, Requested: ₹${(amountToDebit / 100).toFixed(2)}`);
      }

      const newBalance = wallet.balance - amountToDebit;

      await tx.wallet.update({
        where: { id: wallet.id },
        data: {
          balance: newBalance,
        },
      });

      await tx.walletTransaction.create({
        data: {
          walletId: wallet.id,
          type: "DEBIT",
          reason: "TICKET_PURCHASE",
          amount: amountToDebit,
          balanceAfter: newBalance,
          description: `Applied Happenins Wallet balance for booking #${invoiceNumber} (${eventTitle})`,
          bookingId,
          referenceId: invoiceNumber,
        },
      });

      return newBalance;
    });
  }
}
