import { Request, Response, NextFunction } from "express";
import { StaffScannerService } from "../services/staff-scanner.service";
import { UnauthorizedError } from "../errors/app-error";

export class StaffScannerController {
  private staffService = new StaffScannerService();

  loginWithPin = async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { pin, eventId } = req.body;
      const session = await this.staffService.loginWithPin(pin, eventId);
      res.json({
        success: true,
        message: `Welcome ${session.staffName}! Logged into ${session.gateName}.`,
        session,
      });
    } catch (err: unknown) {
      next(err);
    }
  };

  scanTicket = async (req: Request, res: Response, next: NextFunction) => {
    try {
      const { qrHash, gateName: customGate } = req.body;
      const ip = (req.headers["x-forwarded-for"] as string) || req.socket.remoteAddress;
      const userAgent = req.headers["user-agent"];

      let authContext: Parameters<StaffScannerService["scanTicketAtGate"]>[0] = {};

      if (req.staffScanner) {
        authContext = {
          staffScannerId: req.staffScanner.id,
          userId: `staff_${req.staffScanner.id}`,
          gateName: req.staffScanner.gateName,
          staffName: req.staffScanner.staffName,
          allowedTierNames: req.staffScanner.allowedTierNames,
          isOrganizerOrAdmin: false,
        };
      } else if (req.user) {
        const isOrganizerOrAdmin = req.user.role === "ORGANIZER" || req.user.role === "ADMIN";
        authContext = {
          userId: req.user.id,
          gateName: customGate || "Organizer Master Gate",
          staffName: req.user.fullName || "Organizer",
          allowedTierNames: [], // ALL allowed
          isOrganizerOrAdmin,
        };
      } else {
        throw new UnauthorizedError("Scanner authentication or volunteer staff PIN session required.");
      }

      const result = await this.staffService.scanTicketAtGate(
        authContext,
        qrHash,
        ip,
        userAgent
      );

      res.json(result);
    } catch (err: unknown) {
      next(err);
    }
  };

  getStaffScannersForEvent = async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (!req.user) throw new UnauthorizedError("Authentication required.");
      const { eventId } = req.params;
      const scanners = await this.staffService.getStaffScannersForEvent(req.user.id, eventId);
      res.json(scanners);
    } catch (err: unknown) {
      next(err);
    }
  };

  createStaffScanners = async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (!req.user) throw new UnauthorizedError("Authentication required.");
      const { eventId } = req.params;
      const created = await this.staffService.createStaffScanners(req.user.id, eventId, req.body);
      res.status(201).json({
        success: true,
        count: created.length,
        message: `Successfully generated ${created.length} volunteer staff scanner account${created.length > 1 ? "s" : ""}.`,
        scanners: created,
      });
    } catch (err: unknown) {
      next(err);
    }
  };

  updateStaffScanner = async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (!req.user) throw new UnauthorizedError("Authentication required.");
      const { id } = req.params;
      const updated = await this.staffService.updateStaffScanner(req.user.id, id, req.body);
      res.json(updated);
    } catch (err: unknown) {
      next(err);
    }
  };

  deleteStaffScanner = async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (!req.user) throw new UnauthorizedError("Authentication required.");
      const { id } = req.params;
      const result = await this.staffService.deleteStaffScanner(req.user.id, id);
      res.json(result);
    } catch (err: unknown) {
      next(err);
    }
  };

  getGateStats = async (req: Request, res: Response, next: NextFunction) => {
    try {
      if (!req.user) throw new UnauthorizedError("Authentication required.");
      const { eventId } = req.params;
      const stats = await this.staffService.getGateOverviewStats(req.user.id, eventId);
      res.json(stats);
    } catch (err: unknown) {
      next(err);
    }
  };
}
