import { getPrisma } from "../utils/db";
import { BookingQueryRepository } from "./booking/booking-queries.repository";
import { BookingReservationRepository } from "./booking/booking-reservation.repository";
import { BookingConfirmationRepository } from "./booking/booking-confirmation.repository";
import { BookingTransferRepository } from "./booking/booking-transfer.repository";

/** Thin facade over the focused booking repositories in ./booking; public API is unchanged. */
export class BookingRepository {
  private prisma = getPrisma();
  private queries = new BookingQueryRepository(this.prisma);
  private reservations = new BookingReservationRepository(this.prisma, this.queries);
  private confirmations = new BookingConfirmationRepository(this.prisma);
  private transfers = new BookingTransferRepository(this.prisma);

  findById(bookingId: string) { return this.queries.findById(bookingId); }
  findByIdempotencyKey(idempotencyKey: string) { return this.queries.findByIdempotencyKey(idempotencyKey); }
  findByInvoiceNumber(invoiceNumber: string) { return this.queries.findByInvoiceNumber(invoiceNumber); }
  findByUserId(userId: string) { return this.queries.findByUserId(userId); }
  findByEventId(eventId: string) { return this.queries.findByEventId(eventId); }
  getAllConfirmedBookings() { return this.queries.getAllConfirmedBookings(); }

  createReservation(data: Parameters<BookingReservationRepository["createReservation"]>[0]) {
    return this.reservations.createReservation(data);
  }

  confirmBooking(...args: Parameters<BookingConfirmationRepository["confirmBooking"]>) {
    return this.confirmations.confirmBooking(...args);
  }
  releaseExpiredBooking(bookingId: string) { return this.confirmations.releaseExpiredBooking(bookingId); }
  releaseExpiredReservations() { return this.confirmations.releaseExpiredReservations(); }

  applyPromoCode(bookingId: string, promoCodeId: string, discountAmount: number) {
    return this.transfers.applyPromoCode(bookingId, promoCodeId, discountAmount);
  }
  createTransfer(data: Parameters<BookingTransferRepository["createTransfer"]>[0]) { return this.transfers.createTransfer(data); }
  findTransferByCode(transferCode: string) { return this.transfers.findTransferByCode(transferCode); }
  findTransfersByUserId(userId: string) { return this.transfers.findTransfersByUserId(userId); }
  cancelTransfer(transferId: string, senderUserId: string) { return this.transfers.cancelTransfer(transferId, senderUserId); }
  claimTransfer(transferCode: string, recipientUserId: string, recipientEmail: string, newQrHash: string) {
    return this.transfers.claimTransfer(transferCode, recipientUserId, recipientEmail, newQrHash);
  }
}
