import { isFeatureEnabled } from "../config/features";
import { UserRepository } from "../repositories/user.repository";
import { hashPassword, comparePassword, generateSecureToken, hashToken } from "../utils/crypto";
import { UserSession, UserRole } from "../../types";
import { sendSimulatedEmail } from "../utils/emailService";
import { SessionService } from "./session.service";
import { OAuthService } from "./oauth.service";
import { RegistrationVerificationService } from "./registration-verification.service";
import { BadRequestError, ConflictError, ForbiddenError, NotFoundError, UnauthorizedError } from "../errors/app-error";
import { getPrisma } from "../utils/db";
import crypto from "crypto";

const RESET_TTL_MS = 15 * 60 * 1000;
const MAX_RESET_OTP_ATTEMPTS = 5;

export class AuthService {
  private userRepo = new UserRepository();
  private sessionService = new SessionService();
  private oauthService = new OAuthService();
  private registrationService = new RegistrationVerificationService();
  private prisma = getPrisma();

  /** Step 1 of sign-up: stores a pending registration and emails a code. No account or session yet. */
  async register(data: { email: string; fullName: string; password: string }) {
    return this.registrationService.start(data);
  }

  /** Sign-up without the emailed code (FEATURE_EMAIL_VERIFICATION_REQUIRED=false): account + session at once. */
  async registerWithoutVerification(data: { email: string; fullName: string; password: string }, ipAddress?: string, userAgent?: string) {
    return this.registrationService.registerUnverified(data, ipAddress, userAgent);
  }

  /** Step 2 of sign-up: proves mailbox ownership, creates the verified account and starts a session. */
  async verifyRegistration(email: string, code: string, ipAddress?: string, userAgent?: string) {
    return this.registrationService.complete(email, code, ipAddress, userAgent);
  }

  async login(
    data: {
      email: string;
      password?: string;
    },
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ user: UserSession; accessToken: string; rawRefreshToken: string }> {
    const cleanEmail = data.email.trim().toLowerCase();
    let user = await this.userRepo.findByEmail(cleanEmail);

    // Same message for unknown email, Google-only account and wrong password (no account enumeration)
    if (!user || !user.passwordHash) {
      throw new UnauthorizedError('Invalid email address or password. If you signed up with Google, use "Continue with Google".');
    }

    if (!data.password) {
      throw new BadRequestError("Password is required.");
    }

    const passMatches = await comparePassword(data.password, user.passwordHash);
    if (!passMatches) {
      throw new UnauthorizedError('Invalid email address or password. If you signed up with Google, use "Continue with Google".');
    }

    if (!user.isEmailVerified && isFeatureEnabled("EMAIL_VERIFICATION_REQUIRED")) {
      // Legacy accounts created before email verification existed must prove mailbox ownership once
      throw new ForbiddenError("Please verify your email address. Use 'Forgot password' or 'Login with email code' to verify it, then sign in.");
    }

    const { rawRefreshToken, accessToken, user: sessionUser } = await this.sessionService.createSession(
      user.id,
      ipAddress,
      userAgent
    );

    return { user: sessionUser, accessToken, rawRefreshToken };
  }

  async googleOAuthLogin(
    code: string,
    state: string,
    redirectUri: string,
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ user: UserSession; accessToken: string; rawRefreshToken: string }> {
    const googleProfile = await this.oauthService.verifyCodeAndExchange(code, state, redirectUri);

    let user = await this.userRepo.findByEmail(googleProfile.email);

    if (!user) {
      const userId = "usr_" + generateSecureToken(8);
      user = await this.userRepo.createUser({
        id: userId,
        email: googleProfile.email,
        fullName: googleProfile.fullName,
        avatarUrl: googleProfile.avatarUrl,
        role: "USER",
        isEmailVerified: true,
        emailVerifiedAt: new Date(),
      });
    } else if (!user.isEmailVerified) {
      // Pre-registration takeover defence: the password on an account whose email was never
      // verified may belong to someone other than the Google-verified owner. Drop it and
      // terminate any sessions created with it.
      if (await this.userRepo.claimUnverifiedAccount(user.id)) {
        await this.sessionService.revokeAllUserSessions(user.id, "OAUTH_EMAIL_VERIFIED");
      }
      user = (await this.userRepo.findById(user.id)) as typeof user;
    }
    if (googleProfile.fullName && user.fullName !== googleProfile.fullName) {
      user = await this.userRepo.updateFullName(user.id, googleProfile.fullName);
    }

    const { rawRefreshToken, accessToken, user: sessionUser } = await this.sessionService.createSession(
      user.id,
      ipAddress,
      userAgent
    );

    return { user: sessionUser, accessToken, rawRefreshToken };
  }

  async refreshSession(
    rawRefreshToken: string,
    ipAddress?: string,
    userAgent?: string
  ): Promise<{ user: UserSession; accessToken: string; newRawRefreshToken: string }> {
    const { newRawRefreshToken, accessToken, user } = await this.sessionService.rotateSession(
      rawRefreshToken,
      ipAddress,
      userAgent
    );
    return { user, accessToken, newRawRefreshToken };
  }

  async logout(rawRefreshToken: string): Promise<void> {
    if (rawRefreshToken) {
      await this.sessionService.revokeSession(rawRefreshToken, "USER_LOGOUT");
    }
  }

  async promoteUserToOrganizer(
    userId: string,
    data: {
      companyName: string;
      website?: string;
      entityType?: string;
      phone?: string;
      businessAddress?: string;
      taxId?: string;
      representativeTitle?: string;
      bankName?: string;
      bankAccountName?: string;
      bankAccountNumber?: string;
      acceptedTermsAt?: Date;
      acceptedLiability?: boolean;
      acceptedPrivacy?: boolean;
    }
  ): Promise<{ user: UserSession }> {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new NotFoundError("User account not found.");
    }

    await this.userRepo.promoteToOrganizer(userId, data.companyName, data.website, data);

    const sessionUser: UserSession = {
      id: user.id,
      email: user.email,
      fullName: user.fullName,
      avatarUrl: user.avatarUrl,
      role: "ORGANIZER",
    };

    return { user: sessionUser };
  }

  async getOrganizerProfile(userId: string) {
    return this.userRepo.findOrganizerProfileByUserId(userId);
  }

  async forgotPassword(email: string): Promise<{ success: boolean }> {
    const cleanEmail = email.trim().toLowerCase();
    const user = await this.userRepo.findByEmail(cleanEmail);
    if (!user) {
      // Do not leak email existence for privacy/security
      return { success: true };
    }

    const rawToken = generateSecureToken(32);
    const otp = crypto.randomInt(100000, 1000000).toString();

    const tokenHash = hashToken(rawToken);
    const otpHash = hashToken(`${cleanEmail}:${otp}`);
    const expiresAt = new Date(Date.now() + RESET_TTL_MS);

    // Invalidate any earlier pending requests so only the latest code is valid
    await this.prisma.passwordResetToken.updateMany({
      where: { userId: user.id, usedAt: null },
      data: { usedAt: new Date() },
    });

    await this.prisma.passwordResetToken.createMany({
      data: [
        { userId: user.id, tokenHash, expiresAt },
        { userId: user.id, tokenHash: otpHash, expiresAt },
      ],
    });

    const appUrl = process.env.APP_URL || "http://localhost:3000";
    const resetLink = `${appUrl}/?view=reset-password&token=${rawToken}&otp=${otp}&email=${encodeURIComponent(user.email)}`;

    await sendSimulatedEmail(
      user.email,
      `Happenins Password Reset Code: ${otp} 🔑`,
      `Hi ${user.fullName},\n\nWe received a request to reset your Happenins password.\n\n` +
      `========================================\n` +
      `YOUR 6-DIGIT PASSWORD RESET OTP CODE:\n` +
      `  >>>  ${otp}  <<<\n` +
      `========================================\n\n` +
      `Step 1: Enter your 6-digit OTP code on the reset password screen.\n` +
      `Step 2: Generate or enter your new secure password.\n` +
      `Step 3: Save and continue to login.\n\n` +
      `Direct Reset Link:\n${resetLink}\n\n` +
      `This code and link are valid for 15 minutes.\n` +
      `If you did not request this, you can safely ignore this email.\n\n` +
      `Warm regards,\nThe Happenins Security Team`
    );

    return {
      success: true,
    };
  }

  async resetPassword(params: { token?: string; otp?: string; email?: string; newPassword: string }): Promise<void> {
    const { token, otp, email, newPassword } = params;
    if (!newPassword || newPassword.trim().length < 8) {
      throw new BadRequestError("New password must be at least 8 characters in length.");
    }

    let resetRecord: any = null;

    if (token && token.trim()) {
      const tokenHash = hashToken(token.trim());
      resetRecord = await this.prisma.passwordResetToken.findUnique({
        where: { tokenHash },
        include: { user: true },
      });
    } else if (otp && email) {
      // OTP is bound to the email and attempt-limited per account
      const cleanEmail = email.trim().toLowerCase();
      const user = await this.userRepo.findByEmail(cleanEmail);
      const active = user
        ? await this.prisma.passwordResetToken.findMany({
            where: { userId: user.id, usedAt: null, expiresAt: { gt: new Date() } },
          })
        : [];
      if (user && active.some((r) => r.attempts >= MAX_RESET_OTP_ATTEMPTS)) {
        throw new BadRequestError("Too many incorrect attempts. Please request a fresh OTP code.");
      }
      const otpHash = hashToken(`${cleanEmail}:${otp.trim()}`);
      resetRecord = await this.prisma.passwordResetToken.findUnique({
        where: { tokenHash: otpHash },
        include: { user: true },
      });
      if (resetRecord && user && resetRecord.userId !== user.id) resetRecord = null;
      if (!resetRecord && user && active.length > 0) {
        await this.prisma.passwordResetToken.updateMany({
          where: { id: { in: active.map((r) => r.id) } },
          data: { attempts: { increment: 1 } },
        });
      }
    }

    if (!resetRecord || resetRecord.usedAt || resetRecord.expiresAt < new Date()) {
      throw new BadRequestError("Invalid, used, or expired OTP code or reset token. Please request a fresh OTP code.");
    }

    const newHash = await hashPassword(newPassword.trim());
    await this.userRepo.updatePassword(resetRecord.userId, newHash);
    // Receiving the reset code proves ownership of the mailbox
    await this.prisma.user.update({
      where: { id: resetRecord.userId },
      data: { isEmailVerified: true, emailVerifiedAt: resetRecord.user.emailVerifiedAt ?? new Date() },
    });

    // Mark token used
    await this.prisma.passwordResetToken.update({
      where: { id: resetRecord.id },
      data: { usedAt: new Date() },
    });

    // Revoke all existing sessions for security
    await this.sessionService.revokeAllUserSessions(resetRecord.userId, "PASSWORD_RESET");

    await sendSimulatedEmail(
      resetRecord.user.email,
      "Happenins Password Reset Completed 🔒",
      `Hi ${resetRecord.user.fullName},\n\nYour Happenins password was successfully reset. All active user sessions have been terminated for security.\n\nPlease log in with your new password.\n\nWarm regards,\nThe Happenins Security Team`
    );
  }

  async updateProfile(userId: string, data: { fullName: string }): Promise<{ user: UserSession }> {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new NotFoundError("User does not exist.");
    }

    const updatedUser = await this.userRepo.updateFullName(userId, data.fullName);

    const sessionUser: UserSession = {
      id: updatedUser.id,
      email: updatedUser.email,
      fullName: updatedUser.fullName,
      avatarUrl: updatedUser.avatarUrl,
      role: updatedUser.role as UserRole,
    };

    return { user: sessionUser };
  }

  async changePassword(userId: string, data: { oldPassword?: string; newPassword: string }): Promise<void> {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new NotFoundError("User account not found.");
    }

    if (user.passwordHash) {
      if (!data.oldPassword) {
        throw new BadRequestError("Current password is required.");
      }
      const matches = await comparePassword(data.oldPassword, user.passwordHash);
      if (!matches) {
        throw new BadRequestError("Incorrect current password.");
      }
    }

    if (!data.newPassword || data.newPassword.trim().length < 8) {
      throw new BadRequestError("New password must be at least 8 characters in length.");
    }

    const newHash = await hashPassword(data.newPassword.trim());
    await this.userRepo.updatePassword(userId, newHash);

    await this.sessionService.revokeAllUserSessions(userId, "PASSWORD_CHANGED");

    await sendSimulatedEmail(
      user.email,
      "Happenins Password Updated Successfully 🔒",
      `Hi ${user.fullName},\n\nThis is a security alert to confirm that your Happenins account password has been changed.\n\nIf you performed this action, please log in again with your new credentials.\n\nWarm regards,\nThe Happenins Security Team`
    );
  }

  async updateAvatar(userId: string, avatarUrl: string): Promise<{ user: UserSession }> {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new NotFoundError("User does not exist.");
    }

    const updatedUser = await this.userRepo.updateAvatarUrl(userId, avatarUrl);

    const sessionUser: UserSession = {
      id: updatedUser.id,
      email: updatedUser.email,
      fullName: updatedUser.fullName,
      avatarUrl: updatedUser.avatarUrl,
      role: updatedUser.role as UserRole,
    };

    return { user: sessionUser };
  }

  /**
   * Any role change (promotion or demotion) must end existing sessions: the role is embedded in
   * access tokens, so without revocation a demoted user keeps old privileges until the token expires.
   */
  async changeUserRole(userId: string, role: UserRole): Promise<void> {
    const user = await this.userRepo.findById(userId);
    if (!user) throw new NotFoundError("User does not exist.");
    await this.prisma.user.update({ where: { id: userId }, data: { role } });
    await this.sessionService.revokeAllUserSessions(userId, "ROLE_CHANGED");
  }

  async deleteAccount(userId: string): Promise<void> {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new NotFoundError("User does not exist.");
    }

    if (await this.userRepo.hasActiveOrganizedEvents(userId)) {
      throw new ConflictError("Cancel or complete your upcoming events before deleting this account.");
    }

    await this.sessionService.revokeAllUserSessions(userId, "ACCOUNT_DELETED");
    await this.userRepo.anonymiseUser(userId);

    await sendSimulatedEmail(
      user.email,
      "Happenins Account Permanently Deleted 👤❌",
      `Hi ${user.fullName},\n\nThis is a confirmation that your Happenins account has been deleted.\n\nWarm regards,\nThe Happenins Security Team`
    );
  }
}
