import { getPrisma } from "../../utils/db";
import { BookingDTO } from "../../../types";
import { WhatsAppService } from "../whatsapp.service";
import { fastPathInventoryService } from "../inventory-fast-path.service";
import { queueService } from "../queue.service";
import { assertPaymentsEnabled } from "../../config/payment";
import { generateQRHash } from "../../utils/crypto";
import { sendSimulatedEmail } from "../../utils/emailService";
import { bestEffort } from "../../utils/best-effort";
import { logger } from "../../utils/logger";
import { NotFoundError } from "../../errors/app-error";
import { BookingContext } from "./booking-context";
import { errorMessage } from "../../utils/error-message";
import { formatDateIST } from "../../../lib/formatters";

export class BookingConfirmation {
  constructor(private readonly ctx: BookingContext) {}

  async confirmPayment(
    bookingId: string,
    transactionId: string,
    method: string,
    rzpDetails?: { razorpayOrderId?: string; razorpayPaymentId?: string; razorpaySignature?: string }
  ): Promise<BookingDTO> {
    const booking = await this.ctx.bookingRepo.findById(bookingId);
    if (!booking) {
      throw new NotFoundError("Booking does not exist.");
    }
    if (booking.totalAmount > 0) assertPaymentsEnabled();

    // Process confirm state
    const confirmed = await this.ctx.bookingRepo.confirmBooking(booking.id, transactionId, method, rzpDetails);

    // Pillar 2: Finalize Redis atomic inventory hold and clear temporary seat locks
    await fastPathInventoryService.finalizeHold({
      eventId: booking.eventId,
      items: (booking.items || []).map((it: any) => ({
        ticketTierId: it.ticketTierId,
        quantity: it.quantity,
        seatNumbers: it.seatNumbers || undefined,
      })),
    }).catch(bestEffort("fastPathInventoryService.finalizeHold"));

    // Pillar 1: Release admission session so next user waiting in queue can enter immediately
    await queueService.releaseAdmission(booking.userId, booking.eventId).catch(bestEffort("queueService.releaseAdmission"));

    // If wallet amount was applied, debit user's Happenins Wallet
    if (booking.walletAmountApplied && booking.walletAmountApplied > 0) {
      try {
        await this.ctx.walletService.applyWalletDebit(
          booking.userId,
          booking.walletAmountApplied,
          booking.id,
          booking.invoiceNumber,
          booking.event?.title || "Special Performance"
        );
      } catch (err: unknown) {
        logger.error("Wallet debit failed", { message: errorMessage(err) });
      }
    }

    // Generate the CRYPTOGRAPHIC SIGNED GATE QR CODE for the booking confirmation email
    const userEmail = booking.user?.email || "attendee@happenins.com";
    const signedHash = generateQRHash(booking.id, userEmail);

    // Send high-fidelity simulated confirmation email
    const userName = booking.user?.fullName || "Attendee";
    const eventTitle = booking.event?.title || "Happenin Event";
    const invoiceNum = booking.invoiceNumber;
    const totalCents = booking.items.reduce((sum: number, item: any) => sum + (item.ticketTier.price * item.quantity), 0);
    const totalPaidRupees = `₹${(totalCents / 100).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const istTimeStr = formatDateIST(new Date(), { dateStyle: "full", timeStyle: "medium" });

    await sendSimulatedEmail(
      userEmail,
      `Your Ticket Confirmation for ${eventTitle}! 🎫`,
      `Hi ${userName},\n\nThank you for your purchase! Your tickets for "${eventTitle}" have been successfully confirmed.\n\nOrder Details:\n- Invoice Reference: ${invoiceNum}\n- Total Transaction: ${totalPaidRupees}\n- Confirmation Time: ${istTimeStr}\n\nYour Gate Pass: Access your scanned QR code directly inside the Happenins web application under the 'My Tickets' dashboard.\n- Gateway Security Hash: ${signedHash}\n\nWe look forward to seeing you at the experience!\n\nBest wishes,\nThe Happenins Concierge Team`
    );

    // Dispatch WhatsApp Ticket Confirmation Notification from +91 8767164611
    try {
      const customAppUrl = process.env.APP_URL || "https://happenins.com";
      const targetPhone = (booking.user as any)?.phone || WhatsAppService.SENDER_NUMBER;
      const whatsappMsg = WhatsAppService.formatTicketConfirmation(booking, booking.user, customAppUrl);
      await WhatsAppService.dispatchWhatsAppNotification(
        targetPhone,
        whatsappMsg,
        "TICKET_CONFIRMATION",
        { bookingId: booking.id, invoiceNumber: booking.invoiceNumber, totalAmount: booking.totalAmount }
      );
    } catch (err: unknown) {
      logger.error("WhatsApp confirmation failed", { message: errorMessage(err) });
    }

    const refreshed = await this.ctx.bookingRepo.findById(booking.id);
    return this.ctx.mapBookingToDTO(refreshed);
  }

  async releaseExpiredLocks(): Promise<number> {
    return this.ctx.bookingRepo.releaseExpiredReservations();
  }

  async confirmSplitSharePayment(
    bookingId: string,
    shareId: string,
    transactionId: string,
    method: string
  ): Promise<BookingDTO> {
    const booking = await this.ctx.bookingRepo.findById(bookingId);
    if (!booking) {
      throw new NotFoundError("Booking does not exist.");
    }

    const prisma = getPrisma();

    const share = await prisma.bookingSplitShare.findUnique({
      where: { id: shareId },
    });

    if (!share) {
      throw new NotFoundError("Split share record not found.");
    }

    if (share.isPaid) {
      const refreshed = await this.ctx.bookingRepo.findById(bookingId);
      return this.ctx.mapBookingToDTO(refreshed);
    }

    // Update split share as paid
    await prisma.bookingSplitShare.update({
      where: { id: shareId },
      data: {
        isPaid: true,
        paymentId: transactionId,
        paidAt: new Date(),
      },
    });

    // Refresh booking and check if all split shares are now paid
    const refreshedBooking = await this.ctx.bookingRepo.findById(bookingId);
    const allPaid = refreshedBooking.splitShares.every((s: any) => s.isPaid);

    if (allPaid) {
      // Transition booking to CONFIRMED
      await this.ctx.confirmPayment(bookingId, `SPLIT-PAY-${bookingId}`, method);
    }

    const finalBooking = await this.ctx.bookingRepo.findById(bookingId);
    return this.ctx.mapBookingToDTO(finalBooking);
  }
}
