import { BookingRepository } from "../repositories/booking.repository";
import { EventRepository } from "../repositories/event.repository";
import { UserRepository } from "../repositories/user.repository";
import { PromoCodeRepository } from "../repositories/promo.repository";
import { TicketService } from "./ticket.service";
import { InstitutionService } from "./institution.service";
import { InstitutionOtpService } from "./institution-otp.service";
import { WalletService } from "./wallet.service";
import { BookingDTO, TicketTransferDTO } from "../../types";
import { getPrisma } from "../utils/db";
import { BookingContext } from "./booking/booking-context";
import { mapBookingToDTO } from "./booking/booking-mapper";
import { BookingReservation } from "./booking/booking-reservation";
import { BookingConfirmation } from "./booking/booking-confirmation";
import { BookingQueries } from "./booking/booking-queries";
import { BookingTransfers } from "./booking/booking-transfers";
import { BookingAnalytics } from "./booking/booking-analytics";
import { BookingPromo } from "./booking/booking-promo";
import { BookingWallet } from "./booking/booking-wallet";

/**
 * Thin facade over the booking sub-modules in ./booking. Public API is unchanged; the modules
 * read their dependencies through a context whose getters always resolve to the current facade
 * fields (so swapping a field, e.g. in tests, is observed everywhere).
 */
export class BookingService {
  private prisma = getPrisma();
  private bookingRepo = new BookingRepository();
  private eventRepo = new EventRepository();
  private userRepo = new UserRepository();
  private promoRepo = new PromoCodeRepository();
  private institutionService = new InstitutionService();
  private institutionOtpService = new InstitutionOtpService();
  private ticketService = new TicketService();
  private walletService = new WalletService();

  private readonly reservation: BookingReservation;
  private readonly confirmation: BookingConfirmation;
  private readonly queries: BookingQueries;
  private readonly transfers: BookingTransfers;
  private readonly analytics: BookingAnalytics;
  private readonly promo: BookingPromo;
  private readonly wallet: BookingWallet;

  constructor() {
    // eslint-disable-next-line @typescript-eslint/no-this-alias
    const self = this;
    const ctx: BookingContext = {
      get prisma() { return self.prisma; },
      get bookingRepo() { return self.bookingRepo; },
      get eventRepo() { return self.eventRepo; },
      get userRepo() { return self.userRepo; },
      get promoRepo() { return self.promoRepo; },
      get institutionOtpService() { return self.institutionOtpService; },
      get ticketService() { return self.ticketService; },
      get walletService() { return self.walletService; },
      mapBookingToDTO: (booking) => self.mapBookingToDTO(booking),
      confirmPayment: (...args) => self.confirmPayment(...args),
    };
    this.reservation = new BookingReservation(ctx);
    this.confirmation = new BookingConfirmation(ctx);
    this.queries = new BookingQueries(ctx);
    this.transfers = new BookingTransfers(ctx);
    this.analytics = new BookingAnalytics(ctx);
    this.promo = new BookingPromo(ctx);
    this.wallet = new BookingWallet(ctx);
  }

  private mapBookingToDTO(booking: any): BookingDTO {
    return mapBookingToDTO(booking);
  }

  reserveTickets(...args: Parameters<BookingReservation["reserveTickets"]>) {
    return this.reservation.reserveTickets(...args);
  }

  confirmPayment(...args: Parameters<BookingConfirmation["confirmPayment"]>) {
    return this.confirmation.confirmPayment(...args);
  }
  releaseExpiredLocks() { return this.confirmation.releaseExpiredLocks(); }
  confirmSplitSharePayment(...args: Parameters<BookingConfirmation["confirmSplitSharePayment"]>) {
    return this.confirmation.confirmSplitSharePayment(...args);
  }

  getBookingDetails(bookingId: string, userId: string) { return this.queries.getBookingDetails(bookingId, userId); }
  getUserBookings(userId: string) { return this.queries.getUserBookings(userId); }
  getActiveTestBookings() { return this.queries.getActiveTestBookings(); }
  scanQRCheckIn(scannerUserId: string, rawQRInput: string) { return this.queries.scanQRCheckIn(scannerUserId, rawQRInput); }
  generateOrganizerRosterCSV(eventId: string, userId: string) { return this.queries.generateOrganizerRosterCSV(eventId, userId); }
  getWhatsAppConfirmationMessage(bookingId: string, userId: string, targetPhone?: string) {
    return this.queries.getWhatsAppConfirmationMessage(bookingId, userId, targetPhone);
  }
  sendWhatsAppConfirmation(bookingId: string, userId: string, targetPhone?: string) {
    return this.queries.sendWhatsAppConfirmation(bookingId, userId, targetPhone);
  }

  createTicketTransfer(...args: Parameters<BookingTransfers["createTicketTransfer"]>) {
    return this.transfers.createTicketTransfer(...args);
  }
  getTransferDetails(transferCode: string) { return this.transfers.getTransferDetails(transferCode); }
  claimTicketTransfer(recipientUserId: string, transferCode: string) { return this.transfers.claimTicketTransfer(recipientUserId, transferCode); }
  cancelTicketTransfer(senderUserId: string, transferId: string) { return this.transfers.cancelTicketTransfer(senderUserId, transferId); }
  getUserTransfers(userId: string): Promise<TicketTransferDTO[]> { return this.transfers.getUserTransfers(userId); }

  getOrganizerAnalytics(userId: string) { return this.analytics.getOrganizerAnalytics(userId); }
  getEventAnalyticsForOrganizer(userId: string, eventId: string) { return this.analytics.getEventAnalyticsForOrganizer(userId, eventId); }

  validatePromoCode(bookingId: string, code: string) { return this.promo.validatePromoCode(bookingId, code); }
  applyPromoCode(bookingId: string, code: string) { return this.promo.applyPromoCode(bookingId, code); }
  createPromoCode(...args: Parameters<BookingPromo["createPromoCode"]>) { return this.promo.createPromoCode(...args); }
  getEventPromoCodes(userId: string, eventId: string) { return this.promo.getEventPromoCodes(userId, eventId); }
  deletePromoCode(userId: string, id: string) { return this.promo.deletePromoCode(userId, id); }

  getUserWallet(userId: string) { return this.wallet.getUserWallet(userId); }
  applyWalletToBooking(bookingId: string, userId: string) { return this.wallet.applyWalletToBooking(bookingId, userId); }
  removeWalletFromBooking(bookingId: string, userId: string) { return this.wallet.removeWalletFromBooking(bookingId, userId); }
  previewCancellation(bookingId: string, userId: string) { return this.wallet.previewCancellation(bookingId, userId); }
  cancelBooking(bookingId: string, userId: string, reason?: string) { return this.wallet.cancelBooking(bookingId, userId, reason); }
}
